INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('ENGL.G5.WRITIN.T13_SPELLING.a', 'ENGL.G5.WRITIN.T13_SPELLING', 'a', 'identify homophones, words with double consonants and words with double vowels correctly', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
