INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('ENGL.G5.WRITIN.T13_SPELLING.c', 'ENGL.G5.WRITIN.T13_SPELLING', 'c', 'uses homophones, words with double consonants and words with double vowels in sentences correctly', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
