INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.THEME_WORDS', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS', 'english', 5, 'Use words about child rights and responsibilities', ARRAY['ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.b']::text[], 'Chooses the right word from the theme (right, responsibility, protect, education, shelter, health, safe, respect) to complete a sentence, and spots a sentence where one of them is misused, in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.SOUND_IDENTIFY', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS', 'english', 5, 'Pick out words that contain a target sound', ARRAY['ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.a', 'ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.a', 'ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO.c', 'ENGL.G5.LISTEN.T5_LISTENING_COMPREHENS.a', 'ENGL.G5.LISTEN.T7_PRONUNCIATION_AND_VO.a', 'ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO.a', 'ENGL.G5.LISTEN.T11_PRONUNCIATION_AND_VO.a', 'ENGL.G5.LISTEN.T11_PRONUNCIATION_AND_VO.c', 'ENGL.G5.LISTEN.T13_PRONUNCIATION_AND_VO.a']::text[], 'The child picks the words that contain the target sound by how they sound, not how they are spelt: cup, bus and love have /ʌ/; car and father have /ɑː/; hour has no /h/. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","odd one out by sound","sort the words by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.LISTEN_MAIN_IDEA', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS', 'english', 5, 'Listen for the main idea and the details of an oral text and respond', ARRAY['ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.c', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.d', 'ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.c', 'ENGL.G5.LISTEN.T5_LISTENING_COMPREHENS.b']::text[], 'After hearing a short talk or story once, the child says what it was mainly about in one sentence, gives two details, and responds (answers, acts or asks) as the speaker asked. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["what was the talk mainly about","answer a detail question","what should we do now"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'ENGL.G5.READIN.T1_EXTENSIVE_READING', 'english', 5, 'Choose and use reference materials', ARRAY['ENGL.G5.READIN.T1_EXTENSIVE_READING.a', 'ENGL.G5.READIN.T1_EXTENSIVE_READING.c']::text[], 'Chooses the right reference book for a need (dictionary for meaning and spelling, atlas for places, encyclopaedia for facts), puts words in alphabetical order beyond the first letter, and uses guide words to decide whether a word is on a page, in 8 of 10 new questions.', '["choose the correct book","put words in alphabetical order","decide from guide words"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T1_WORD_CLASS_DEMONSTRA.DEMONSTRATIVES', 'ENGL.G5.GRAMMA.T1_WORD_CLASS_DEMONSTRA', 'english', 5, 'Use this, these, that and those', ARRAY['ENGL.G5.GRAMMA.T1_WORD_CLASS_DEMONSTRA.a', 'ENGL.G5.GRAMMA.T1_WORD_CLASS_DEMONSTRA.b']::text[], 'Chooses or writes this, these, that or those so that it agrees in number with the noun and fits the distance (near or far), in 8 of 10 new sentences, and finds the one wrong demonstrative in a short note.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.FILL_FORM', 'ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F', 'english', 5, 'Record the right details in a variety of forms', ARRAY['ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.a']::text[], 'The child fills personal, school, parent or guardian, county, hobby and sport details into the right boxes, in the format asked (capitals, date order), with no box left empty. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["fill in the form","correct this form","what goes in this box"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.DESIGN_FORM', 'ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F', 'english', 5, 'Design a simple form to collect information', ARRAY['ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.b']::text[], 'The child designs a form with a title, a clear label and enough space for each detail needed, in a sensible order, with a line for a signature and date. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["design a club form","add the missing box","is this form clear"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.ORAL_SENTENCES', 'ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO', 'english', 5, 'Make sentences aloud with the theme words', ARRAY['ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.b', 'ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO.b', 'ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.b', 'ENGL.G5.LISTEN.T5_LISTENING_COMPREHENS.c', 'ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.c', 'ENGL.G5.LISTEN.T7_PRONUNCIATION_AND_VO.b', 'ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO.b', 'ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO.b', 'ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO.d', 'ENGL.G5.LISTEN.T11_PRONUNCIATION_AND_VO.b', 'ENGL.G5.LISTEN.T12_PRONUNCIATION_AND_VO.b', 'ENGL.G5.LISTEN.T13_PRONUNCIATION_AND_VO.b']::text[], 'The child says full, correct sentences that use each theme word in its right meaning and as the right part of speech, without the home-language pattern (Me I ...). Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say a sentence with the word","tell the class using these words","answer in a full sentence"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.SPEAKER_FEELINGS', 'ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO', 'english', 5, 'Tell how a speaker feels from words, tone and gestures', ARRAY['ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.d', 'ENGL.G5.LISTEN.T11_PRONUNCIATION_AND_VO.d', 'ENGL.G5.LISTEN.T13_PRONUNCIATION_AND_VO.d']::text[], 'The child names a speaker''s feeling from the tone of voice, the face, the gestures and the words together, and says which clue shows it. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["how does the speaker feel","which clue shows it","match the feeling to the cue"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS', 'ENGL.G5.READIN.T2_INTENSIVE_READING', 'english', 5, 'Identify characters, places and events', ARRAY['ENGL.G5.READIN.T2_INTENSIVE_READING.a']::text[], 'Names the characters and the places in a short story and puts its main events in the order they happened, in 8 of 10 new passages.', '["short comprehension: choose","short comprehension: type","put the events in order"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.PREDICT', 'ENGL.G5.READIN.T2_INTENSIVE_READING', 'english', 5, 'Predict what happens next', ARRAY['ENGL.G5.READIN.T2_INTENSIVE_READING.b', 'ENGL.G5.READIN.T3_INTENSIVE_READING_NA.b']::text[], 'Uses clues in the title and the story to choose the most likely next event, and says which clue supports it, in 8 of 10 new passages.', '["choose the best prediction","choose the clue that supports it"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'ENGL.G5.READIN.T2_INTENSIVE_READING', 'english', 5, 'Answer factual questions from a text', ARRAY['ENGL.G5.READIN.T2_INTENSIVE_READING.c', 'ENGL.G5.READIN.T3_INTENSIVE_READING_NA.d', 'ENGL.G5.READIN.T4_INTENSIVE_READING_CO.d', 'ENGL.G5.READIN.T6_INTENSIVE_READING_CO.c', 'ENGL.G5.READIN.T9_INTENSIVE_READING_DE.d', 'ENGL.G5.READIN.T10_INTENSIVE_READING.b', 'ENGL.G5.READIN.T11_INTENSIVE_READING.c', 'ENGL.G5.READIN.T12_INTENSIVE_READING.c']::text[], 'Finds an answer that is stated in the text, tells true from false and not stated, and does not pick a detail that sits near the answer, in 8 of 10 new passages.', '["short comprehension: choose","true, false or not stated","short comprehension: type"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'ENGL.G5.READIN.T2_INTENSIVE_READING', 'english', 5, 'Answer inferential questions from a text', ARRAY['ENGL.G5.READIN.T2_INTENSIVE_READING.c', 'ENGL.G5.READIN.T3_INTENSIVE_READING_NA.d', 'ENGL.G5.READIN.T4_INTENSIVE_READING_CO.d', 'ENGL.G5.READIN.T6_INTENSIVE_READING_CO.c', 'ENGL.G5.READIN.T9_INTENSIVE_READING_DE.d', 'ENGL.G5.READIN.T10_INTENSIVE_READING.b', 'ENGL.G5.READIN.T11_INTENSIVE_READING.c', 'ENGL.G5.READIN.T12_INTENSIVE_READING.c']::text[], 'Works out what the text does not say outright (why a character acts, how they feel, what a clue means) and does not give an answer the text contradicts or merely repeats, in 8 of 10 new passages.', '["short comprehension: choose","stated or worked out"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES', 'ENGL.G5.READIN.T2_INTENSIVE_READING', 'english', 5, 'Use context clues to find the meaning of a word', ARRAY['ENGL.G5.READIN.T2_INTENSIVE_READING.d', 'ENGL.G5.READIN.T6_INTENSIVE_READING_CO.b', 'ENGL.G5.READIN.T12_INTENSIVE_READING.b', 'ENGL.G5.READIN.T6_INTENSIVE_READING_CO.a', 'ENGL.G5.READIN.T8_FLUENCY_IN_READING.a']::text[], 'Uses the words around an unfamiliar word to choose its meaning, and says which words gave the clue, in 8 of 10 new passages.', '["short comprehension: choose","choose the clue words"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.COLLECTIVE_NOUNS', 'ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV', 'english', 5, 'Use collective nouns for groups', ARRAY['ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.a', 'ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.b']::text[], 'Names the usual collective noun for a group of animals or things (a flock of birds, a herd of cattle, a swarm of bees, a bunch of bananas, a school of fish) and does not use one group word for every group, in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.REFLEXIVE_PRONOUNS', 'ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV', 'english', 5, 'Use reflexive pronouns', ARRAY['ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.a', 'ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.b']::text[], 'Uses myself, yourself, himself, herself, itself, ourselves, yourselves and themselves when the doer and the receiver are the same, and does not write hisself, theirselves or an object pronoun in their place, in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.PLAN_COMPOSITION', 'ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE', 'english', 5, 'Select relevant points when planning a composition', ARRAY['ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.a']::text[], 'Before writing, the child lists points that keep to the topic, drops the ones that do not, and orders the rest into beginning, middle and end. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which point fits the topic","order the plan","cross out the point that does not belong"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.OPEN_COMPOSITION', 'ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE', 'english', 5, 'Write an open-ended composition that flows', ARRAY['ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.b']::text[], 'The child writes a composition from a plan in paragraphs, with ideas linked by time words and conjunctions, keeping to the topic from start to finish. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write about","continue the story","write from the plan"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_EXPRESSIONS', 'ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO', 'english', 5, 'Choose polite words and expressions', ARRAY['ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO.a', 'ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO.d', 'ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO.e']::text[], 'Chooses the polite expression for a table or classroom situation (please, thank you, excuse me, may I, pardon, sorry) and the polite reply to thanks or an apology, in 8 of 10 new situations.', '["choose the polite expression","fill the gap","spot the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T3_INTENSIVE_READING_NA.RELATE_TO_LIFE', 'ENGL.G5.READIN.T3_INTENSIVE_READING_NA', 'english', 5, 'Relate events and ideas in a text to one''s own life', ARRAY['ENGL.G5.READIN.T3_INTENSIVE_READING_NA.a', 'ENGL.G5.READIN.T3_INTENSIVE_READING_NA.e', 'ENGL.G5.READIN.T6_INTENSIVE_READING_CO.d', 'ENGL.G5.READIN.T10_INTENSIVE_READING.a', 'ENGL.G5.READIN.T11_INTENSIVE_READING.a', 'ENGL.G5.READIN.T12_INTENSIVE_READING.d']::text[], 'The child links an event or idea in the text to a real experience and says how they are alike and different, keeping to what the text says. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["has this ever happened to you","what would you do","how is this like your home"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T3_INTENSIVE_READING_NA.VISUALISE', 'ENGL.G5.READIN.T3_INTENSIVE_READING_NA', 'english', 5, 'Create mental pictures of events, characters and places in a text', ARRAY['ENGL.G5.READIN.T3_INTENSIVE_READING_NA.c', 'ENGL.G5.READIN.T4_INTENSIVE_READING_CO.c', 'ENGL.G5.READIN.T9_INTENSIVE_READING_DE.b', 'ENGL.G5.READIN.T11_INTENSIVE_READING.b', 'ENGL.G5.READIN.T12_INTENSIVE_READING.a']::text[], 'The child builds a picture from all the describing words in the text (place, time, what people wear and do) and chooses or draws the picture that matches every detail. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which picture matches","draw what you read","what does the place look like"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.TOO_TO', 'ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN', 'english', 5, 'Use too ... to and too ... for', ARRAY['ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.a', 'ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.b']::text[], 'Completes and builds sentences with too + adjective + to + verb and too + adjective + for + person (too hot to drink, too heavy for me), and does not add for to or a that-clause, in 8 of 10 new sentences.', '["choose the correct sentence","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.MUST_SHOULD_ADVERB', 'ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN', 'english', 5, 'Use must and should with an adverb', ARRAY['ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.a', 'ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.b']::text[], 'Writes must or should followed by the base verb and an adverb of manner (You must speak politely), without to, -s, -ing or an adjective where the adverb belongs, in 8 of 10 new sentences.', '["choose the correct sentence","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T3_MECHANICS_OF_WRITING.CURSIVE', 'ENGL.G5.WRITIN.T3_MECHANICS_OF_WRITING', 'english', 5, 'Read and write legibly in joined letters (cursive)', ARRAY['ENGL.G5.WRITIN.T3_MECHANICS_OF_WRITING.a', 'ENGL.G5.WRITIN.T3_MECHANICS_OF_WRITING.b']::text[], 'The child recognises cursive script and writes words with the letters joined by the right strokes, the same slant and size, and clear spaces between words. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["copy in joined writing","is this text in cursive","join these letters"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.ROAD_SAFETY_WORDS', 'ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO', 'english', 5, 'Use words about road safety', ARRAY['ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.d']::text[], 'Chooses the right road safety word (pedestrian, zebra crossing, speed limit, helmet, seat belt, pavement, signal) to complete a sentence, in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO', 'english', 5, 'Stress words correctly, including words whose stress changes the meaning', ARRAY['ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.a', 'ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.c']::text[], 'The child says REcord (a noun) and reCORD (a verb), PREsent and preSENT, and stresses the theme words correctly: PEdestrian is wrong, peDEStrian is right. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say it as a noun and as a verb","which syllable is strong","list words that change with stress"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T4_INTENSIVE_READING_CO.READ_VISUALS', 'ENGL.G5.READIN.T4_INTENSIVE_READING_CO', 'english', 5, 'Name visuals, predict from them and judge whether they suit their purpose', ARRAY['ENGL.G5.READIN.T4_INTENSIVE_READING_CO.a', 'ENGL.G5.READIN.T4_INTENSIVE_READING_CO.b', 'ENGL.G5.READIN.T4_INTENSIVE_READING_CO.e']::text[], 'The child names a visual (poster, map, chart, illustration, mnemonic), uses its picture, title and words to predict what a text will be about, and says whether it does its job. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what kind of visual is this","what will the text be about","is this poster suitable"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T4_WORD_CLASS_POSSESSIV.POSSESSIVES', 'ENGL.G5.GRAMMA.T4_WORD_CLASS_POSSESSIV', 'english', 5, 'Use possessive pronouns and their determiners', ARRAY['ENGL.G5.GRAMMA.T4_WORD_CLASS_POSSESSIV.a', 'ENGL.G5.GRAMMA.T4_WORD_CLASS_POSSESSIV.b']::text[], 'Tells a possessive determiner (my, your, her, our, their) from a possessive pronoun (mine, yours, hers, ours, theirs), writes each in the right place and never writes her''s, our''s or their''s, in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.LETTER_PARTS', 'ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F', 'english', 5, 'Identify the parts of a friendly letter and judge its words', ARRAY['ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.a', 'ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.c']::text[], 'The child names the address, date, greeting, body, closing and name in a sample letter and says whether words and phrases suit a friendly letter (warm, not official). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["label the parts","which part is missing","is this phrase right for a friendly letter"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER', 'ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F', 'english', 5, 'Write a friendly letter in the correct format', ARRAY['ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.b']::text[], 'The child writes a friendly letter with every part in place, a warm opening, paragraphs of news and a fitting closing. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a letter to","reply to this letter","correct the letter"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T5_LISTENING_COMPREHENS.EXPRESS_FEELINGS', 'ENGL.G5.LISTEN.T5_LISTENING_COMPREHENS', 'english', 5, 'Show feelings with the voice, face and gestures when speaking and listening', ARRAY['ENGL.G5.LISTEN.T5_LISTENING_COMPREHENS.d', 'ENGL.G5.LISTEN.T7_PRONUNCIATION_AND_VO.d', 'ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO.e', 'ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO.e']::text[], 'The child changes voice, face and gestures to match the feeling of what is said (happy, worried, angry), and shows interest as a listener by nodding and facing the speaker. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["tell it happily, then sadly","show you are listening","perform the verse with feeling"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SCAN_SKIM', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI', 'english', 5, 'Scan for details and skim for the gist', ARRAY['ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.b', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.c', 'ENGL.G5.READIN.T13_EXTENSIVE_READING.c']::text[], 'Finds a name, time, place or number in a notice or timetable by scanning, and says what a text is mostly about by skimming, in 8 of 10 new texts.', '["scan: type the detail","scan: choose the detail","skim: choose what it is about"]'::jsonb, '["procedure"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SELECT_READING', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI', 'english', 5, 'Choose reading materials that suit the purpose, interest and level', ARRAY['ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.a', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.e', 'ENGL.G5.READIN.T7_EXTENSIVE_READING_FI.a', 'ENGL.G5.READIN.T7_EXTENSIVE_READING_FI.c', 'ENGL.G5.READIN.T11_INTENSIVE_READING.d', 'ENGL.G5.READIN.T13_EXTENSIVE_READING.a', 'ENGL.G5.READIN.T13_EXTENSIVE_READING.d']::text[], 'The child chooses a book, newspaper, magazine or poem by purpose, interest and language level after looking at the title, the blurb and a page, not by the cover alone. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which book would you choose","is this text right for","why is this book suitable"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.INDEPENDENT_READING', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI', 'english', 5, 'Read a variety of fiction and non-fiction independently', ARRAY['ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.d', 'ENGL.G5.READIN.T7_EXTENSIVE_READING_FI.b', 'ENGL.G5.READIN.T13_EXTENSIVE_READING.b']::text[], 'The child reads a range of books, poems and magazines alone, keeps a short reading log and can tell a classmate what each was about and whether it was worth reading. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["reading log","book talk","retell to a partner"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.COMPARATIVE_SUPERLATIVE', 'ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE', 'english', 5, 'Use comparative and superlative adjectives', ARRAY['ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.a', 'ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.c']::text[], 'Forms and uses -er/-est, more/most and the irregular forms good-better-best and bad-worse-worst, with than for two things and the for three or more, and avoids double comparatives (more taller) and gooder, in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.ADJECTIVE_ORDER', 'ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE', 'english', 5, 'Put adjectives in order', ARRAY['ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.b']::text[], 'Places two or three adjectives before the noun in the usual order (opinion, size, age, shape, colour, material) and does not put the adjective after the noun as in Kiswahili, in 8 of 10 new phrases.', '["choose the correct phrase","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_PARTS', 'ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR', 'english', 5, 'Identify the parts of a narrative composition', ARRAY['ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.a']::text[], 'The child names the title, introduction (characters and setting), body (the events and the problem) and conclusion (how it ended and the lesson) in a sample story. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["label the parts","which part is this sentence from","what is missing"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION', 'ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR', 'english', 5, 'Create a coherent narrative composition', ARRAY['ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.b', 'ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.c', 'ENGL.G5.WRITIN.T8_CREATIVE_WRITING.c']::text[], 'The child writes a story in the past tense with a clear beginning, a problem and an ending, linked paragraphs and some vivid language (a simile or a proverb that fits). Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a story about","write a story with this ending","use a simile and a proverb in your story"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO', 'english', 5, 'Sort and say statements and questions by rising and falling intonation', ARRAY['ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.a', 'ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.d']::text[], 'The child hears and uses a falling tune for statements and WH questions and a rising tune for yes or no questions, and stresses the word that carries the meaning. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["up or down at the end","sort the sentences","say it as a question"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO', 'english', 5, 'Pronounce the target sounds correctly', ARRAY['ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.b', 'ENGL.G5.LISTEN.T7_PRONUNCIATION_AND_VO.c', 'ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO.c', 'ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.b', 'ENGL.G5.LISTEN.T12_PRONUNCIATION_AND_VO.a']::text[], 'The child says the Grade 5 target sounds (/f/ and /v/, /k/ and /g/, /s/ and /z/, the weak /ə/) so that fan and van, coat and goat, bus and buzz are heard as different words. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say the word after the teacher","read the pairs aloud","say a tongue twister"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.FEW_LITTLE', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE', 'english', 5, 'Use few, a few, little and a little', ARRAY['ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.a', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.b', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.c']::text[], 'Chooses few or a few for things that can be counted and little or a little for things that cannot, and knows that few and little say "hardly any" while a few and a little say "some", in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.QUANTIFIERS_OTHER', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE', 'english', 5, 'Use a lot of, each, all, enough, most and least', ARRAY['ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.a', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.b', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.c']::text[], 'Chooses and places a lot of, lots of, each, all, enough, most and least correctly, with the right verb after each, and writes most of the learners (not most of learners), in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T6_CREATIVE_WRITING_PIC.PICTORIAL_COMPOSITION', 'ENGL.G5.WRITIN.T6_CREATIVE_WRITING_PIC', 'english', 5, 'Choose a topic and write a composition from pictures', ARRAY['ENGL.G5.WRITIN.T6_CREATIVE_WRITING_PIC.a', 'ENGL.G5.WRITIN.T6_CREATIVE_WRITING_PIC.b', 'ENGL.G5.WRITIN.T6_CREATIVE_WRITING_PIC.c']::text[], 'The child chooses a fitting topic for a set of pictures, writes a linked story that covers every picture in order, and adds details the pictures suggest. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["give the pictures a title","write the story the pictures tell","which pictures make a good story"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US.FUTURE_WILL_SHALL', 'ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US', 'english', 5, 'Use will and shall for the future', ARRAY['ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US.a', 'ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US.b', 'ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US.c']::text[], 'Writes will or shall followed by the base verb to talk about the future, and does not write will goes, will went, will going or a present tense where a future is meant, in 8 of 10 new sentences.', '["choose the correct sentence","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.COMMAS', 'ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING', 'english', 5, 'Use the comma', ARRAY['ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.a', 'ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.b']::text[], 'Puts commas between the items in a list, after an opening word or phrase and before the words a speaker says, and does not put a comma between a subject and its verb, in 8 of 10 new sentences.', '["choose the correct sentence","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.DIRECT_SPEECH', 'ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING', 'english', 5, 'Punctuate direct speech with double quotation marks', ARRAY['ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.a', 'ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.b']::text[], 'Puts double quotation marks round the exact words spoken, a capital letter at the start of the speech, and the comma, question mark or full stop inside the closing marks, in 8 of 10 new sentences.', '["choose the correct sentence","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO.PROVERBS', 'ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO', 'english', 5, 'Know proverbs and their meanings', ARRAY['ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO.a', 'ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO.d']::text[], 'Matches a common English proverb to its meaning, finishes a proverb, and uses it for the situation it fits, in 8 of 10 new questions.', '["choose the meaning","finish the proverb","choose the situation"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T8_FLUENCY_IN_READING.READ_FLUENTLY', 'ENGL.G5.READIN.T8_FLUENCY_IN_READING', 'english', 5, 'Read a text accurately, with expression and at the right speed', ARRAY['ENGL.G5.READIN.T8_FLUENCY_IN_READING.b']::text[], 'The child reads a Grade 5 text aloud in phrases, at talking speed, with few slips, pausing at punctuation and letting the voice show questions and feelings. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read aloud to the teacher","read the dialogue in parts","reread for expression"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T8_SENTENCES.QUESTION_TAGS', 'ENGL.G5.GRAMMA.T8_SENTENCES', 'english', 5, 'Use question tags', ARRAY['ENGL.G5.GRAMMA.T8_SENTENCES.a', 'ENGL.G5.GRAMMA.T8_SENTENCES.b']::text[], 'Adds the right question tag to a statement: the same helper verb, the opposite sign (is/isn''t, does/doesn''t, can/can''t), and a pronoun, never the same tag for every sentence, in 8 of 10 new sentences.', '["choose the correct tag","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T8_CREATIVE_WRITING.SIMILES', 'ENGL.G5.WRITIN.T8_CREATIVE_WRITING', 'english', 5, 'Identify and use similes', ARRAY['ENGL.G5.WRITIN.T8_CREATIVE_WRITING.a', 'ENGL.G5.WRITIN.T8_CREATIVE_WRITING.b']::text[], 'Spots a simile (a comparison with like or as), completes a common simile (as brave as a lion) and tells a simile from a plain statement or a metaphor, in 8 of 10 new questions.', '["choose the simile","fill the gap","finish the comparison"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO.SPEAK_FLUENTLY', 'ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO', 'english', 5, 'Speak accurately, at the right speed and with expression on a topic', ARRAY['ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO.c', 'ENGL.G5.LISTEN.T12_PRONUNCIATION_AND_VO.c']::text[], 'The child talks for about two minutes on a topic in clear sentences, at a speed listeners can follow, with expression and without long hesitation. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["talk for two minutes","present to the class","answer and say more"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T9_INTENSIVE_READING_DE.MAIN_IDEA', 'ENGL.G5.READIN.T9_INTENSIVE_READING_DE', 'english', 5, 'Find the main idea of a paragraph', ARRAY['ENGL.G5.READIN.T9_INTENSIVE_READING_DE.a']::text[], 'Chooses the sentence or title that covers the whole paragraph, and does not pick one detail or an idea the paragraph does not discuss, in 8 of 10 new passages.', '["short comprehension: choose the main idea","choose the best title"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.READIN.T9_INTENSIVE_READING_DE.SUMMARISE', 'ENGL.G5.READIN.T9_INTENSIVE_READING_DE', 'english', 5, 'Summarise the main points', ARRAY['ENGL.G5.READIN.T9_INTENSIVE_READING_DE.c', 'ENGL.G5.READIN.T10_INTENSIVE_READING.c']::text[], 'Chooses the summary that keeps the main points in order and leaves out the small details and the writer''s own opinion, in 8 of 10 new passages.', '["choose the best summary","choose what a summary leaves out"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.ADVERBS', 'ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS', 'english', 5, 'Identify and use adverbs of manner, time, place and frequency', ARRAY['ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.a', 'ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.b', 'ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.d']::text[], 'Tells whether an adverb shows manner, time, place or frequency, and uses the adverb (not the adjective) after the verb (runs quickly, sings well), in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake","say what the adverb tells us"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.COULD_WOULD', 'ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS', 'english', 5, 'Use could and would', ARRAY['ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.c']::text[], 'Uses could for past ability or a polite request and would for a polite request or an imagined result, followed by the base verb, and builds how many ... could/would questions, in 8 of 10 new sentences.', '["choose the correct sentence","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.APOSTROPHE', 'ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING', 'english', 5, 'Use the apostrophe', ARRAY['ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.a', 'ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.b']::text[], 'Uses the apostrophe for belonging (Juma''s bag, the girls'' room) and for missing letters (don''t, it''s), tells its from it''s, and does not put an apostrophe in a plain plural (banana''s), in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.EXCLAMATION_MARK', 'ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING', 'english', 5, 'Use the exclamation mark', ARRAY['ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.a', 'ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.b']::text[], 'Ends a sentence of strong feeling, surprise, warning or a shout with an exclamation mark, keeps the full stop for ordinary statements and the question mark for questions, in 8 of 10 new sentences.', '["choose the correct sentence","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.MOOD_FEELINGS', 'ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO', 'english', 5, 'Tell the mood or feeling in a narrative', ARRAY['ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.a']::text[], 'Reads a few lines of a narrative and names the feeling or mood, using the words and actions as evidence, and does not name the opposite feeling from one cheerful or sad word, in 8 of 10 new extracts.', '["choose the feeling","choose the evidence"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY', 'ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO', 'english', 5, 'Interrupt politely during a conversation', ARRAY['ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.c']::text[], 'The child waits for a pause and uses Excuse me, sorry to interrupt, but ... or May I add something?, and gives the turn back. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the polite way","what would you say","when should you interrupt"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS', 'ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI', 'english', 5, 'Join sentences with but, or, yet, because, since and also', ARRAY['ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.a', 'ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.b', 'ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.c']::text[], 'Chooses the conjunction that fits the meaning (contrast, choice, reason) and uses only one joining word in a sentence (not Because ..., so ...), in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIBE_FROM_TEXT', 'ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES', 'english', 5, 'Describe people and things mentioned in a text', ARRAY['ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.a']::text[], 'The child finds the words in a text that describe a person or thing (looks, character, sounds, smells) and uses them to say what it is like. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which words describe","what is she like","find the describing words"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION', 'ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES', 'english', 5, 'Write and critique a descriptive composition of 120 to 160 words', ARRAY['ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.b', 'ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.c']::text[], 'The child writes a 120 to 160 word description that uses the senses and exact words, in a clear order, and comments on another description''s word choice, relevance and flow. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["describe a place","improve this description","give feedback on a classmate''s description"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.INTERROGATIVES', 'ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE', 'english', 5, 'Ask questions with how, what, when, why, who', ARRAY['ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.a', 'ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.b']::text[], 'Chooses the question word that fits the answer given, puts the helper verb before the subject (What are you doing?), and uses how much more and when/who/why/what else correctly, in 8 of 10 new questions.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T11_SPELLING.HOMOPHONES', 'ENGL.G5.WRITIN.T11_SPELLING', 'english', 5, 'Spell and use homophones', ARRAY['ENGL.G5.WRITIN.T11_SPELLING.b', 'ENGL.G5.WRITIN.T13_SPELLING.a', 'ENGL.G5.WRITIN.T13_SPELLING.b', 'ENGL.G5.WRITIN.T13_SPELLING.c']::text[], 'Chooses the right word from a pair or trio of words that sound alike (there/their, to/too/two, hear/here, write/right, piece/peace) from the meaning of the sentence, in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T11_SPELLING.HOMONYMS', 'ENGL.G5.WRITIN.T11_SPELLING', 'english', 5, 'Use homonyms in the right meaning', ARRAY['ENGL.G5.WRITIN.T11_SPELLING.b']::text[], 'Recognises that one spelling can carry two meanings (bank, bat, bark, light, match) and picks the sentence that uses the word in the meaning asked for, in 8 of 10 new questions.', '["choose the sentence with this meaning","choose the meaning in a sentence"]'::jsonb, '["reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T12_WORD_CLASS_NOUNS.SAME_SINGULAR_PLURAL', 'ENGL.G5.GRAMMA.T12_WORD_CLASS_NOUNS', 'english', 5, 'Use nouns that are the same in singular and plural', ARRAY['ENGL.G5.GRAMMA.T12_WORD_CLASS_NOUNS.a', 'ENGL.G5.GRAMMA.T12_WORD_CLASS_NOUNS.b']::text[], 'Uses sheep, fish, deer, aircraft, series and species (and does not write sheeps or deers), keeps the verb in agreement with the number meant, and still writes the irregular plurals children, men, feet and teeth, in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_PARTS', 'ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D', 'english', 5, 'Identify the parts of a diary or journal', ARRAY['ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.a']::text[], 'The child names the date, the optional greeting (Dear Diary), the events in the first person and past tense, and the writer''s feelings in a sample entry. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["label the parts","what is missing","is this a diary entry"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_WRITING', 'ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D', 'english', 5, 'Write a diary or journal entry in the right format', ARRAY['ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.b']::text[], 'The child writes dated entries in the first person and past tense about real events and feelings, one entry per day. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write today''s entry","write a week of entries","correct the entry"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.LISTEN.T13_PRONUNCIATION_AND_VO.JUDGE_ORAL', 'ENGL.G5.LISTEN.T13_PRONUNCIATION_AND_VO', 'english', 5, 'Judge how well words, similes and gestures were used in a presentation', ARRAY['ENGL.G5.LISTEN.T13_PRONUNCIATION_AND_VO.c']::text[], 'The child comments on a classmate''s talk with one strength and one improvement, about the choice of words, similes and gestures, not about the person. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["give a friend feedback","what was good and what could improve","was this simile right for the talk"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_TIME_PLACE', 'ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI', 'english', 5, 'Use in, on and at for time and place', ARRAY['ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.a', 'ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.b']::text[], 'Chooses in, on or at for times (at 8 o''clock, on Monday, in June) and places (at the gate, on the table, in the room), in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_DIRECTION', 'ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI', 'english', 5, 'Use into, towards, to and through for direction', ARRAY['ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.a', 'ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.b']::text[], 'Chooses into, towards, to or through for movement, and does not write to home or entered into, in 8 of 10 new sentences.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G5.WRITIN.T13_SPELLING.DOUBLE_LETTERS', 'ENGL.G5.WRITIN.T13_SPELLING', 'english', 5, 'Spell words with double consonants and double vowels', ARRAY['ENGL.G5.WRITIN.T13_SPELLING.a', 'ENGL.G5.WRITIN.T13_SPELLING.b', 'ENGL.G5.WRITIN.T13_SPELLING.c', 'ENGL.G5.WRITIN.T11_SPELLING.a', 'ENGL.G5.READIN.T1_EXTENSIVE_READING.b']::text[], 'Spells words such as summer, happy, address, letter, coffee, see, food, week and queen with the right doubled letters, in 8 of 10 new words, and chooses the correctly spelt word in a sentence.', '["choose the correct spelling","type the spelling","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
