INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_DIRECTION', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_DIRECTION', 'skill', 'essential', 'Grade 4 English taught it first. Proposed, to confirm by a Kenyan English teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_DIRECTION', 'ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_TIME_PLACE', 'skill', 'essential', 'In, on and at first. Proposed, to confirm by a Kenyan English teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENGL.G5.WRITIN.T13_SPELLING.DOUBLE_LETTERS', 'ENGL.G4.WRITIN.T13_SPELLING.a', 'outcome', 'essential', 'Proposed: this skill builds on it. To confirm by a Kenyan English teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENGL.G5.WRITIN.T13_SPELLING.DOUBLE_LETTERS', 'ENGL.G4.WRITIN.T13_SPELLING.DOUBLE_CONSONANTS', 'skill', 'essential', 'Grade 4 English taught it first. Proposed, to confirm by a Kenyan English teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.THEME_WORDS.M_VOC_RIGHT_RESPONSIBILITY', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.THEME_WORDS', 'Mixes up right and responsibility.', '{"question":"Every child has a ___ to go to school.","wrong_answer":"responsibility","correct_answer":"right"}'::jsonb, 'Does not separate what you are given from what you must do.', 'right and responsibility in one sentence.', 'A right is something every child is entitled to. A responsibility is something you must do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.THEME_WORDS.M_VOC_NEAR_MEANING', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.THEME_WORDS', 'Chooses a word with a related meaning that does not fit the sentence.', '{"question":"Parents should ___ their children from harm.","wrong_answer":"respect","correct_answer":"protect"}'::jsonb, 'Knows the topic words but not their exact meaning.', 'Two theme words close in meaning.', 'Replace the gap with each word and test the meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.SOUND_IDENTIFY.M5_SI_LETTER_NOT_SOUND', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.SOUND_IDENTIFY', 'Picks words by the letter, not the sound.', '{"question":"Which word has the vowel sound in \"cup\"? put, bus","wrong_answer":"put","correct_answer":"bus"}'::jsonb, 'The child matches the letter u, not the sound.', 'Offer "put" beside "bus" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say the words aloud: bus sounds like cup; put does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.SOUND_IDENTIFY.M5_SI_UH_AH', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.SOUND_IDENTIFY', 'Hears /ʌ/ (cup) and /ɑː/ (car) as one sound.', '{"question":"Which word has the vowel in \"car\"? cut, cart","wrong_answer":"cut","correct_answer":"cart"}'::jsonb, 'Kiswahili and many home languages have one a sound.', 'Offer "cut" beside "cart" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Car and cart are long and open; cut is short.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.SOUND_IDENTIFY.M5_SI_SILENT_H', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.SOUND_IDENTIFY', 'Counts a silent h as the /h/ sound.', '{"question":"Which word starts with the /h/ sound? hour, house","wrong_answer":"hour","correct_answer":"house"}'::jsonb, 'Every written h is assumed to be heard.', 'Offer "hour" beside "house" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hour starts with a vowel sound; the h is silent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.SOUND_IDENTIFY.M5_SI_P_B', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.SOUND_IDENTIFY', 'Swaps /p/ and /b/.', '{"question":"Which word starts with /p/? bat, pat","wrong_answer":"bat","correct_answer":"pat"}'::jsonb, 'Some home languages do not keep p and b apart.', 'Offer "bat" beside "pat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'P is a puff of air with no voice; b buzzes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.SOUND_IDENTIFY.M5_SI_NG_N', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.SOUND_IDENTIFY', 'Hears /ŋ/ (sing) as /n/ or as n plus g.', '{"question":"Which word ends with the same sound as \"sing\"? sin, ring","wrong_answer":"sin","correct_answer":"ring"}'::jsonb, 'The ng sound is heard as two sounds or as n.', 'Offer "sin" beside "ring" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ng is one sound made at the back of the mouth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.LISTEN_MAIN_IDEA.M5_LM_DETAIL_AS_MAIN', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.LISTEN_MAIN_IDEA', 'Gives a detail as the main idea.', '{"question":"The talk was about why children should go to school; it mentioned a boy called Otieno. Main idea?","wrong_answer":"Otieno","correct_answer":"Every child has a right to go to school."}'::jsonb, 'A name or example sticks in memory.', 'Offer "Otieno" beside "Every child has a right to go to school." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask: what was the whole talk about?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.LISTEN_MAIN_IDEA.M5_LM_FIRST_SENTENCE', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.LISTEN_MAIN_IDEA', 'Takes the first sentence heard as the main idea.', '{"question":"A talk starts \"Good morning\" and is about clean water. Main idea?","wrong_answer":"greeting the class","correct_answer":"keeping water clean"}'::jsonb, 'The start of the talk is treated as its point.', 'Offer "greeting the class" beside "keeping water clean" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The main idea is what most of the talk explains.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.LISTEN_MAIN_IDEA.M5_LM_NO_RESPONSE', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.LISTEN_MAIN_IDEA', 'Does not do what the speaker asked.', '{"question":"The speaker says: \"Please write down one right of a child.\" What do you do?","wrong_answer":"nothing","correct_answer":"write down one right"}'::jsonb, 'The child listens for content but not for the request.', 'Offer "nothing" beside "write down one right" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen for what the speaker wants you to do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.LISTEN_MAIN_IDEA.M5_LM_OWN_OPINION', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.LISTEN_MAIN_IDEA', 'Gives his or her own view as what the speaker said.', '{"question":"What did the speaker say about chores?","wrong_answer":"Chores are boring.","correct_answer":"Children should help at home."}'::jsonb, 'Own feelings replace the speaker''s message.', 'Offer "Chores are boring." beside "Children should help at home." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tell what the speaker said, not what you think.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.THEME_WORDS.M5_VOC_RIGHT_AS_WANT', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.THEME_WORDS', 'Thinks a right is anything a child wants.', '{"question":"Which is a child''s right?","wrong_answer":"a new phone","correct_answer":"education"}'::jsonb, 'Want and need are not told apart.', 'Offer "a new phone" beside "education" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A right is something every child needs to grow and be safe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.THEME_WORDS.M5_VOC_ABUSE_ANY_RULE', 'ENGL.G5.LISTEN.T1_LISTENING_COMPREHENS.THEME_WORDS', 'Calls any rule or punishment abuse.', '{"question":"A parent asks a child to do homework. This is ...","wrong_answer":"abuse","correct_answer":"guidance (a responsibility)"}'::jsonb, 'The word abuse is learnt as "anything I do not like".', 'Offer "abuse" beside "guidance (a responsibility)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Abuse is harm; a fair rule is guidance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS.M_REF_WRONG_SOURCE', 'ENGL.G5.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'Chooses the wrong reference book for the need (an atlas for the meaning of a word).', '{"question":"Which book tells you the meaning of the word \"harvest\"?","wrong_answer":"an atlas","correct_answer":"a dictionary"}'::jsonb, 'Does not know what each book is for.', 'A book that fits another need among the options.', 'Dictionary: meaning and spelling. Atlas: maps and places. Encyclopaedia: facts about a subject.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS.M_REF_ALPHA_FIRST_LETTER', 'ENGL.G5.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'Sorts words by the first letter only.', '{"question":"Put in alphabetical order: bag, bat, back, ball.","wrong_answer":"bag, bat, back, ball","correct_answer":"back, bag, ball, bat"}'::jsonb, 'Stops when the first letters match.', 'Words that start with the same letter.', 'When the first letters match, look at the second letter, then the third.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS.M_REF_GUIDE_WORDS', 'ENGL.G5.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'Cannot use guide words to decide if a word is on the page.', '{"question":"Is \"mango\" on the page with guide words \"maize\" and \"market\"?","wrong_answer":"No","correct_answer":"Yes"}'::jsonb, 'Compares only the first letter, or does not know what guide words are.', 'A word that sits between the guide words alphabetically.', 'Guide words are the first and last words on the page. Everything on the page comes between them in alphabetical order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS.M5_REF_SUBJECT_ENCYCLOPAEDIA', 'ENGL.G5.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'Uses a general dictionary for a subject topic.', '{"question":"Where would you find how the heart pumps blood?","wrong_answer":"a dictionary","correct_answer":"a science encyclopaedia"}'::jsonb, 'Every reference book seems the same.', 'Offer "a dictionary" beside "a science encyclopaedia" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Subject facts are in a subject encyclopaedia.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T1_WORD_CLASS_DEMONSTRA.DEMONSTRATIVES.M_DEM_THIS_PLURAL', 'ENGL.G5.GRAMMA.T1_WORD_CLASS_DEMONSTRA.DEMONSTRATIVES', 'Uses this or that with a plural noun.', '{"question":"Look at ___ books on my desk.","wrong_answer":"this","correct_answer":"these"}'::jsonb, 'Learns "this" as the word for pointing and does not match it to singular or plural.', 'A plural noun after this/that, with the same sentence also offered with these/those.', 'Point to one object and say this, to two and say these. Say the noun first: one book, two books.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T1_WORD_CLASS_DEMONSTRA.DEMONSTRATIVES.M_DEM_THESE_SINGULAR', 'ENGL.G5.GRAMMA.T1_WORD_CLASS_DEMONSTRA.DEMONSTRATIVES', 'Uses these or those with a singular noun.', '{"question":"___ pencil is mine.","wrong_answer":"These","correct_answer":"This"}'::jsonb, 'Over-corrects after learning that "these" is the word for many things.', 'A singular noun with these/those among the options.', 'Count the things. One thing needs this or that.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T1_WORD_CLASS_DEMONSTRA.DEMONSTRATIVES.M_DEM_NEAR_FAR', 'ENGL.G5.GRAMMA.T1_WORD_CLASS_DEMONSTRA.DEMONSTRATIVES', 'Mixes up near words (this, these) and far words (that, those).', '{"question":"Mama is holding a cup. \"___ cup is mine,\" she said.","wrong_answer":"That","correct_answer":"This"}'::jsonb, 'Does not use the position of the speaker to choose.', 'A sentence that says where the thing is (in my hand, across the field).', 'Use this and these for things near you, that and those for things far away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T1_WORD_CLASS_DEMONSTRA.DEMONSTRATIVES.M_DEM_THEM', 'ENGL.G5.GRAMMA.T1_WORD_CLASS_DEMONSTRA.DEMONSTRATIVES', 'Writes "them" in place of these or those in front of a noun.', '{"question":"Pass me ___ mangoes, please.","wrong_answer":"them","correct_answer":"those"}'::jsonb, 'Them is heard in speech before a noun; it is a pronoun, not a pointing word.', 'The option "them" before a noun.', 'Them stands alone (Pass them to me). Before a noun use these or those.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.FILL_FORM.M5_FF_COUNTY_TOWN', 'ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.FILL_FORM', 'Writes a town in the county box.', '{"question":"County: ___","wrong_answer":"Kitale","correct_answer":"Trans Nzoia"}'::jsonb, 'The child does not know the difference between a town and a county.', 'Offer "Kitale" beside "Trans Nzoia" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The county is the bigger area: Trans Nzoia, not Kitale.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.FILL_FORM.M5_FF_DATE_ORDER', 'ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.FILL_FORM', 'Writes the date in the wrong order for the form.', '{"question":"Date of birth (DD/MM/YYYY): 14 March 2015","wrong_answer":"03/14/2015","correct_answer":"14/03/2015"}'::jsonb, 'A date format seen on a phone is copied.', 'Offer "03/14/2015" beside "14/03/2015" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Follow the order the form shows: day, month, year.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.FILL_FORM.M5_FF_GUARDIAN', 'ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.FILL_FORM', 'Writes his or her own details in the parent or guardian box.', '{"question":"Parent or guardian''s name: ___","wrong_answer":"Amina Wekesa (the child)","correct_answer":"Mary Wekesa"}'::jsonb, 'The child fills every box about himself or herself.', 'Offer "Amina Wekesa (the child)" beside "Mary Wekesa" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'This box is about the adult who cares for you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.FILL_FORM.M5_FF_ALL_CAPS_IGNORED', 'ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.FILL_FORM', 'Ignores the instruction to write in capital letters.', '{"question":"Name (BLOCK LETTERS): ___","wrong_answer":"amina","correct_answer":"AMINA"}'::jsonb, 'Block letters is an unknown term.', 'Offer "amina" beside "AMINA" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Block letters means capitals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.DESIGN_FORM.M5_DF_NO_SPACE', 'ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.DESIGN_FORM', 'Leaves too little space for the answers.', '{"question":"Is a tiny box big enough for a full address?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'The child designs for neatness, not use.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Leave enough room for the longest answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.DESIGN_FORM.M5_DF_VAGUE_LABEL', 'ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.DESIGN_FORM', 'Uses labels that do not say what is wanted.', '{"question":"Better label: \"Number\" or \"Phone number\"?","wrong_answer":"Number","correct_answer":"Phone number"}'::jsonb, 'The designer knows what is meant and forgets the reader.', 'Offer "Number" beside "Phone number" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Make every label exact.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.DESIGN_FORM.M5_DF_MISSING_DETAIL', 'ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.DESIGN_FORM', 'Leaves out a detail the form needs.', '{"question":"A club form has Name and Class. What is missing for the club to call home?","wrong_answer":"nothing","correct_answer":"a parent''s phone number"}'::jsonb, 'The purpose of the form is not thought through.', 'Offer "nothing" beside "a parent''s phone number" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask: what will the form be used for?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.DESIGN_FORM.M5_DF_QUESTIONS_AS_LABELS', 'ENGL.G5.WRITIN.T1_FUNCTIONAL_WRITING_F.DESIGN_FORM', 'Writes long questions instead of short labels.', '{"question":"Better label?","wrong_answer":"What is the name that you were given at birth?","correct_answer":"Full name"}'::jsonb, 'Forms are confused with question papers.', 'Offer "What is the name that you were given at birth?" beside "Full name" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use short labels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.ORAL_SENTENCES.M5_OS_ME_I', 'ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.ORAL_SENTENCES', 'Starts a sentence with "Me I".', '{"question":"Say a sentence with \"celebrate\".","wrong_answer":"Me I celebrate Jamhuri Day.","correct_answer":"I celebrate Jamhuri Day."}'::jsonb, 'A direct carry-over of the Kiswahili emphasis (Mimi ...).', 'Offer "Me I celebrate Jamhuri Day." beside "I celebrate Jamhuri Day." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use I alone at the start.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.ORAL_SENTENCES.M5_OS_ONE_WORD', 'ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.ORAL_SENTENCES', 'Answers with the word alone, not a sentence.', '{"question":"Use \"parade\" in a sentence.","wrong_answer":"Parade.","correct_answer":"We watched the parade on Madaraka Day."}'::jsonb, 'The child thinks saying the word is enough.', 'Offer "Parade." beside "We watched the parade on Madaraka Day." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A sentence has who and what happened.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.ORAL_SENTENCES.M5_OS_WRONG_MEANING', 'ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.ORAL_SENTENCES', 'Uses the theme word with the wrong meaning.', '{"question":"Use \"pedestrian\" in a sentence.","wrong_answer":"The pedestrian drove the bus.","correct_answer":"The pedestrian crossed at the zebra crossing."}'::jsonb, 'The meaning is guessed from the topic.', 'Offer "The pedestrian drove the bus." beside "The pedestrian crossed at the zebra crossing." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check the meaning before you use the word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.ORAL_SENTENCES.M5_OS_WRONG_CLASS', 'ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.ORAL_SENTENCES', 'Uses a noun as a verb or a verb as a noun.', '{"question":"Use \"celebration\" in a sentence.","wrong_answer":"We celebration Christmas.","correct_answer":"The celebration was at our church."}'::jsonb, 'Word families (celebrate, celebration) are mixed up.', 'Offer "We celebration Christmas." beside "The celebration was at our church." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Celebration is a thing; celebrate is the action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.SPEAKER_FEELINGS.M5_SF_WORDS_ONLY', 'ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.SPEAKER_FEELINGS', 'Reads only the words and ignores the tone.', '{"question":"In a shaking voice, a girl says, \"I am fine.\" She feels ...","wrong_answer":"fine","correct_answer":"nervous or upset"}'::jsonb, 'The dictionary meaning wins over the voice.', 'Offer "fine" beside "nervous or upset" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The tone and face can show a feeling the words hide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.SPEAKER_FEELINGS.M5_SF_LOUD_ANGRY', 'ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.SPEAKER_FEELINGS', 'Thinks a loud voice always means anger.', '{"question":"At a national celebration, a speaker shouts, \"Happy Jamhuri Day!\" She feels ...","wrong_answer":"angry","correct_answer":"excited and proud"}'::jsonb, 'Loudness is linked only to anger.', 'Offer "angry" beside "excited and proud" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Loud can be excited or proud; look at the face too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.SPEAKER_FEELINGS.M5_SF_ONE_CLUE', 'ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.SPEAKER_FEELINGS', 'Decides on one clue and ignores the others.', '{"question":"A boy smiles but his voice shakes as he speaks to the class. He is ...","wrong_answer":"happy","correct_answer":"nervous"}'::jsonb, 'The child stops at the first clue.', 'Offer "happy" beside "nervous" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Put all the clues together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.SPEAKER_FEELINGS.M5_SF_OWN_FEELING', 'ENGL.G5.LISTEN.T2_PRONUNCIATION_AND_VO.SPEAKER_FEELINGS', 'Names his or her own feeling about the topic.', '{"question":"The speaker sounds sad about the floods. How does the speaker feel?","wrong_answer":"I feel bored","correct_answer":"sad"}'::jsonb, 'The question is read as about the listener.', 'Offer "I feel bored" beside "sad" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The question asks about the speaker.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS.M_ELEM_MIXES_CHARACTER_PLACE', 'ENGL.G5.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS', 'Names a place when asked for a character, or the other way round.', '{"question":"Who is the story mainly about?","wrong_answer":"the market","correct_answer":"Achieng"}'::jsonb, 'Picks a noun from the first sentence without checking its job.', 'A place and a person offered together.', 'A character is a person or animal that acts. A place is where the story happens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS.M_ELEM_MINOR_FOR_MAIN', 'ENGL.G5.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS', 'Names a minor character as the main one.', '{"question":"Who is the main character?","wrong_answer":"the shopkeeper","correct_answer":"Kamau"}'::jsonb, 'Picks the first name mentioned.', 'A character who appears briefly.', 'The main character is the one the story follows most.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS.M_ELEM_ORDER_REVERSED', 'ENGL.G5.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS', 'Puts events in reverse order or starts from the most exciting event.', '{"question":"Put the events in the order they happened.","wrong_answer":"last event first","correct_answer":"order of the story"}'::jsonb, 'Remembers the ending best.', 'The ending event offered first.', 'Go through the story from the start and number each event as it happens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS.M_ELEM_ORDER_SWAPPED', 'ENGL.G5.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS', 'Swaps two neighbouring events.', '{"question":"Put the events in the order they happened.","wrong_answer":"two swapped","correct_answer":"order of the story"}'::jsonb, 'Does not check each linking word.', 'Two events that are close together.', 'Look for time words like then, soon after, later.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.PREDICT.M_PRED_NO_CLUE', 'ENGL.G5.READIN.T2_INTENSIVE_READING.PREDICT', 'Predicts something that has no support in the text.', '{"question":"What will probably happen next?","wrong_answer":"a prediction with no clue","correct_answer":"a prediction from a clue"}'::jsonb, 'Guesses from personal experience rather than the text.', 'A dramatic event with no clue in the passage.', 'Find a clue in the passage first, then predict.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.PREDICT.M_PRED_CONTRADICTS', 'ENGL.G5.READIN.T2_INTENSIVE_READING.PREDICT', 'Predicts something the text makes unlikely.', '{"question":"What will probably happen next?","wrong_answer":"a prediction that goes against the text","correct_answer":"a prediction that fits the text"}'::jsonb, 'Does not reread the facts.', 'An event the passage rules out.', 'Check that the prediction does not go against what you have read.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.PREDICT.M_PRED_ALREADY_HAPPENED', 'ENGL.G5.READIN.T2_INTENSIVE_READING.PREDICT', 'Says something that has already happened.', '{"question":"What will probably happen next?","wrong_answer":"something already told","correct_answer":"something still to happen"}'::jsonb, 'Repeats the last sentence.', 'An option that repeats the end of the passage.', 'A prediction is about what is NOT yet told.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M_FACT_NEARBY_DETAIL', 'ENGL.G5.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Picks a detail from the passage that is nearby but does not answer the question.', '{"question":"What did Achieng buy at the market?","wrong_answer":"a nearby detail","correct_answer":"the stated answer"}'::jsonb, 'Matches a word in the question to the same word in the passage.', 'A detail from the same sentence as the answer.', 'Find the exact sentence that answers the question. Check the wh- word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M_FACT_NOT_STATED_AS_TRUE', 'ENGL.G5.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Says "true" for something the text does not say.', '{"question":"The passage says the bus was late. True, false or not stated?","wrong_answer":"True","correct_answer":"Not stated"}'::jsonb, 'Fills the gap with what seems likely.', 'A sentence that sounds likely but is never written.', 'True means the passage says it. If you cannot find it, it is not stated.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M_FACT_FALSE_AS_NOT_STATED', 'ENGL.G5.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Says "not stated" when the passage says the opposite.', '{"question":"The passage says Wafula walked to school. True, false or not stated?","wrong_answer":"Not stated","correct_answer":"False"}'::jsonb, 'Does not look for a sentence that contradicts the statement.', 'A statement the passage contradicts.', 'If the passage says the opposite, the statement is false.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M_FACT_OUTSIDE_KNOWLEDGE', 'ENGL.G5.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Answers from what the child knows, not from the passage.', '{"question":"How many people were at the meeting?","wrong_answer":"a number from memory","correct_answer":"the number in the passage"}'::jsonb, 'Uses own experience instead of the text.', 'An answer that is true in life but different from the passage.', 'The passage is the authority. Find the sentence in it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS.M_INFER_REPEATS_TEXT', 'ENGL.G5.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'Repeats a sentence from the text when asked to work something out.', '{"question":"Why do you think Mercy was smiling?","wrong_answer":"a repeated sentence","correct_answer":"a reason from clues"}'::jsonb, 'Treats an inference question as a find-it question.', 'An answer copied from the passage that does not say why.', 'Ask: what clues does the text give? What do they show?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS.M_INFER_CONTRADICTS', 'ENGL.G5.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'Gives an answer that goes against the text.', '{"question":"How did Otieno feel?","wrong_answer":"the opposite feeling","correct_answer":"the feeling shown by the clues"}'::jsonb, 'Takes one word and ignores the rest.', 'The opposite feeling offered beside the right one.', 'Check all the clues: what he said, what he did, what happened.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS.M_INFER_OVERREACH', 'ENGL.G5.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'Gives an answer that goes far beyond the clues.', '{"question":"What can you tell about Mama from the passage?","wrong_answer":"an unsupported claim","correct_answer":"a supported claim"}'::jsonb, 'Builds a story that the text does not support.', 'A dramatic reason with no clue in the passage.', 'An inference must be backed by something written in the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES.M_CTX_COMMON_MEANING', 'ENGL.G5.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES', 'Gives the word''s commonest meaning instead of the one the passage needs.', '{"question":"In the passage, what does \"bank\" mean?","wrong_answer":"a place for money","correct_answer":"the side of the river"}'::jsonb, 'Does not read the words around it.', 'The commonest meaning offered beside the right one.', 'Reread the sentence with each meaning in place of the word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES.M_CTX_LOOKS_LIKE', 'ENGL.G5.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES', 'Chooses a meaning from how the word looks or sounds.', '{"question":"What does \"ravenous\" mean?","wrong_answer":"a word that looks similar","correct_answer":"very hungry"}'::jsonb, 'Matches the word to a known word with a similar shape.', 'A distractor that sounds like the word.', 'Ignore the shape and read the clue words around it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES.M_CTX_OPPOSITE', 'ENGL.G5.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES', 'Chooses the opposite meaning.', '{"question":"What does \"reluctant\" mean?","wrong_answer":"eager","correct_answer":"unwilling"}'::jsonb, 'Misreads a "but" or "although" clue.', 'The opposite meaning offered.', 'Look for words like but, although, however. They flip the meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M_FACT_MISSES_STATED', 'ENGL.G5.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Says false or not stated for something the passage does state, perhaps in different words.', '{"question":"The passage says Wafula walked to school. True, false or not stated?","wrong_answer":"Not stated","correct_answer":"True"}'::jsonb, 'Looks for the exact words and misses a rewording.', 'A true statement that rewords the passage.', 'Look for the idea, not the exact words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M_FACT_FALSE_AS_TRUE', 'ENGL.G5.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Says true for a statement the passage contradicts.', '{"question":"The passage says the bus was early. True, false or not stated?","wrong_answer":"True","correct_answer":"False"}'::jsonb, 'Reads quickly and matches only the topic.', 'A statement that changes one detail of the passage.', 'Check each detail of the statement against the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES.M_CTX_WRONG_CLUE', 'ENGL.G5.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES', 'Chooses words that do not help to find the meaning.', '{"question":"Which words help you understand the word \"ravenous\"?","wrong_answer":"on Tuesday","correct_answer":"had not eaten all day"}'::jsonb, 'Picks words next to the target word, not words about its meaning.', 'Words from the same sentence that do not explain the word.', 'Ask: which words tell me what the word means?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS.M_ELEM_WRONG_PLACE', 'ENGL.G5.READIN.T2_INTENSIVE_READING.STORY_ELEMENTS', 'Names a different place from the story.', '{"question":"Where does the story take place?","wrong_answer":"a different place in the story","correct_answer":"the place named for the scene"}'::jsonb, 'Remembers a place but not the one the question asks about.', 'Another place named in the passage.', 'Find the sentence that says where the event happened.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.PREDICT.M5_PRED_WISH', 'ENGL.G5.READIN.T2_INTENSIVE_READING.PREDICT', 'Predicts what he or she wishes would happen, not what the clues show.', '{"question":"The clouds are black and the wind is strong. What will happen?","wrong_answer":"they will go swimming","correct_answer":"it will rain"}'::jsonb, 'Hope replaces evidence.', 'Offer "they will go swimming" beside "it will rain" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use the clues, not your wishes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS.M5_INFER_NOT_STATED', 'ENGL.G5.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'Says "the text does not say" to an inference question.', '{"question":"\"Amina packed an umbrella.\" Why?","wrong_answer":"The text does not say.","correct_answer":"She expected rain."}'::jsonb, 'Only stated answers are seen as allowed.', 'Offer "The text does not say." beside "She expected rain." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Inference questions want a reason from clues.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.COLLECTIVE_NOUNS.M_COLL_WRONG_ANIMAL', 'ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.COLLECTIVE_NOUNS', 'Uses the group word of one animal for another animal.', '{"question":"A ___ of cattle was crossing the road.","wrong_answer":"flock","correct_answer":"herd"}'::jsonb, 'Learns a few group words and uses one of them for every group.', 'The group word of a different animal as a distractor.', 'Match a group word to the animal: flock of birds or sheep, herd of cattle, swarm of bees.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.COLLECTIVE_NOUNS.M_COLL_THING_MIX', 'ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.COLLECTIVE_NOUNS', 'Uses an animal group word for things (a herd of keys), or a thing group word for animals.', '{"question":"Wambui carried a ___ of bananas home.","wrong_answer":"herd","correct_answer":"bunch"}'::jsonb, 'Treats collective nouns as one list for everything.', 'An animal group word offered for fruit, keys or books.', 'Bunch is for things that grow or hang together: bananas, keys, flowers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.COLLECTIVE_NOUNS.M_COLL_OF_MISSING', 'ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.COLLECTIVE_NOUNS', 'Leaves out "of" after the collective noun.', '{"question":"We saw a flock birds on the roof.","wrong_answer":"a flock birds","correct_answer":"a flock of birds"}'::jsonb, 'Kiswahili puts the group word and noun together without a small linking word.', 'A sentence with "of" missing among the options.', 'Say the whole pattern: a flock OF birds, a herd OF cows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.COLLECTIVE_NOUNS.M_COLL_PLURAL_S', 'ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.COLLECTIVE_NOUNS', 'Puts -s on the thing instead of using the group word, or writes the group word as plural when one group is meant.', '{"question":"Three ___ of sheep were on the hill.","wrong_answer":"flock","correct_answer":"flocks"}'::jsonb, 'Does not see that "three" asks for the plural group word.', 'A number before the group word.', 'Count the groups, not the animals: one flock, three flocks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.REFLEXIVE_PRONOUNS.M_REFL_HISSELF', 'ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.REFLEXIVE_PRONOUNS', 'Writes hisself or theirselves.', '{"question":"Juma made the kite all by ___.","wrong_answer":"hisself","correct_answer":"himself"}'::jsonb, 'Builds the word from his and their, which are the possessive words, instead of him and them.', 'hisself and theirselves among the options.', 'Say: himself, themselves. The first part is him and them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.REFLEXIVE_PRONOUNS.M_REFL_OBJECT_PRONOUN', 'ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.REFLEXIVE_PRONOUNS', 'Uses me, you, us or them where the doer and the receiver are the same person.', '{"question":"I cut ___ with the knife.","wrong_answer":"me","correct_answer":"myself"}'::jsonb, 'Kiswahili uses one verb form (ni-ji-) for this, so English needs a separate learned word.', 'A first or second person sentence where the doer is also the receiver.', 'If I do it to me, say myself. The word ends in self.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.REFLEXIVE_PRONOUNS.M_REFL_SINGULAR_PLURAL', 'ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.REFLEXIVE_PRONOUNS', 'Writes ourself, yourselfs or themself, or mixes one self with many people.', '{"question":"We taught ___ to swim.","wrong_answer":"ourself","correct_answer":"ourselves"}'::jsonb, 'Does not change self to selves for more than one person.', 'ourself and yourselfs among the options.', 'One person: self. More than one person: selves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.REFLEXIVE_PRONOUNS.M_REFL_WRONG_PERSON', 'ENGL.G5.GRAMMA.T2_WORD_CLASS_COLLECTIV.REFLEXIVE_PRONOUNS', 'Uses a reflexive pronoun for a different person (myself for he).', '{"question":"Amina hurt ___ at the market.","wrong_answer":"myself","correct_answer":"herself"}'::jsonb, 'Remembers that the word ends in self but not which person it matches.', 'A reflexive pronoun for the wrong person among the options.', 'Ask who did it. Amina is she, so herself.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.PLAN_COMPOSITION.M5_PC_IRRELEVANT', 'ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.PLAN_COMPOSITION', 'Keeps points that do not fit the topic.', '{"question":"Topic: Madaraka Day. Which point does not belong?","wrong_answer":"We watched the parade.","correct_answer":"My cousin has a bicycle."}'::jsonb, 'Every idea that comes up is kept.', 'Offer "We watched the parade." beside "My cousin has a bicycle." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Cross out points that leave the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.PLAN_COMPOSITION.M5_PC_NO_ORDER', 'ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.PLAN_COMPOSITION', 'Lists points with no order.', '{"question":"Order: speech, arrive at the stadium, go home","wrong_answer":"speech, go home, arrive","correct_answer":"arrive, speech, go home"}'::jsonb, 'Points are written as they come.', 'Offer "speech, go home, arrive" beside "arrive, speech, go home" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Number the points in the order they happen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.PLAN_COMPOSITION.M5_PC_TOO_FEW', 'ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.PLAN_COMPOSITION', 'Plans only one point.', '{"question":"Is one point enough for a composition?","wrong_answer":"Yes","correct_answer":"No: three or four"}'::jsonb, 'The child writes the plan as a title.', 'Offer "Yes" beside "No: three or four" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plan a beginning, two or three middle points and an end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.PLAN_COMPOSITION.M5_PC_SENTENCES_IN_PLAN', 'ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.PLAN_COMPOSITION', 'Writes the whole composition as the plan.', '{"question":"What does a plan look like?","wrong_answer":"full paragraphs","correct_answer":"short notes"}'::jsonb, 'The difference between planning and writing is unclear.', 'Offer "full paragraphs" beside "short notes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A plan is short notes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.OPEN_COMPOSITION.M5_OC_DRIFT', 'ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.OPEN_COMPOSITION', 'Starts on the topic and drifts away from it.', '{"question":"Topic: A national celebration. Last paragraph is about a football match on another day. Is that right?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'One idea leads to another.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Reread each paragraph against the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.OPEN_COMPOSITION.M5_OC_NO_PARAGRAPHS', 'ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.OPEN_COMPOSITION', 'Writes one long block.', '{"question":"How many paragraphs for a beginning, middle and end?","wrong_answer":"one","correct_answer":"at least three"}'::jsonb, 'Paragraphing is not yet a habit.', 'Offer "one" beside "at least three" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A new paragraph for each new part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.OPEN_COMPOSITION.M5_OC_AND_THEN', 'ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.OPEN_COMPOSITION', 'Links every idea with and then.', '{"question":"Improve the linking.","wrong_answer":"and then ... and then","correct_answer":"first, later, after that, finally"}'::jsonb, 'A small set of linking words.', 'Offer "and then ... and then" beside "first, later, after that, finally" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Vary your linking words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.OPEN_COMPOSITION.M5_OC_MEMORISED', 'ENGL.G5.WRITIN.T2_CREATIVE_WRITING_OPE.OPEN_COMPOSITION', 'Writes a memorised composition that does not fit the topic.', '{"question":"Topic: My best gift. Writes \"A visit to the zoo\".","wrong_answer":"the zoo composition","correct_answer":"a composition about a gift"}'::jsonb, 'A composition learnt by heart is reused.', 'Offer "the zoo composition" beside "a composition about a gift" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Write for the topic you are given.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_EXPRESSIONS.M_POL_DEMAND', 'ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_EXPRESSIONS', 'Uses a command where a polite request is needed.', '{"question":"At the table you want the salt. You say, \"___.\"","wrong_answer":"Give me the salt","correct_answer":"Please may I have the salt"}'::jsonb, 'Uses the shortest form from home language or speech.', 'A command beside a polite request.', 'Start with please, may I, or could you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_EXPRESSIONS.M_POL_WRONG_REPLY', 'ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_EXPRESSIONS', 'Gives the wrong reply to thanks or sorry.', '{"question":"Someone says \"Thank you.\" You reply, \"___.\"","wrong_answer":"Sorry","correct_answer":"You are welcome"}'::jsonb, 'Mixes up the replies to thanks and to apologies.', 'sorry offered as a reply to thank you.', 'Thank you: you are welcome. Sorry: that is all right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_EXPRESSIONS.M_POL_EXCUSE_SORRY', 'ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_EXPRESSIONS', 'Says sorry when excuse me is needed, or the other way round.', '{"question":"You want to pass in front of an adult. You say, \"___.\"","wrong_answer":"Sorry","correct_answer":"Excuse me"}'::jsonb, 'Does not separate asking for room from saying you are sorry.', 'sorry offered where you ask for something.', 'Excuse me: to ask, to pass, to interrupt. Sorry: when you have done something wrong.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_EXPRESSIONS.M5_POL_COMPLIMENT_RUDE', 'ENGL.G5.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_EXPRESSIONS', 'Gives a compliment that is really a criticism.', '{"question":"Compliment the cook.","wrong_answer":"The food is good for once.","correct_answer":"The food is delicious, thank you."}'::jsonb, 'Teasing is used as praise.', 'Offer "The food is good for once." beside "The food is delicious, thank you." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A compliment only praises.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T3_INTENSIVE_READING_NA.RELATE_TO_LIFE.M5_RL_RETELL', 'ENGL.G5.READIN.T3_INTENSIVE_READING_NA.RELATE_TO_LIFE', 'Retells the text instead of linking it to life.', '{"question":"How is the story like your life?","wrong_answer":"Achieng ate with her hands and her aunt scolded her.","correct_answer":"At home we also wash our hands before eating."}'::jsonb, 'The child repeats what is known.', 'Offer "Achieng ate with her hands and her aunt scolded her." beside "At home we also wash our hands before eating." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say something from your own life.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T3_INTENSIVE_READING_NA.RELATE_TO_LIFE.M5_RL_SURFACE', 'ENGL.G5.READIN.T3_INTENSIVE_READING_NA.RELATE_TO_LIFE', 'Links on a small surface detail.', '{"question":"The story is about a boy who is kind to a new pupil. How is it like your life?","wrong_answer":"I also have a school bag.","correct_answer":"A new girl came to our class and I helped her."}'::jsonb, 'Any shared detail seems enough.', 'Offer "I also have a school bag." beside "A new girl came to our class and I helped her." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Link the main event, not a small object.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T3_INTENSIVE_READING_NA.RELATE_TO_LIFE.M5_RL_UNRELATED', 'ENGL.G5.READIN.T3_INTENSIVE_READING_NA.RELATE_TO_LIFE', 'Tells a memory that has nothing to do with the text.', '{"question":"Text: table manners. Link?","wrong_answer":"I went to Mombasa.","correct_answer":"We do not talk with food in our mouths at home."}'::jsonb, 'Any memory is offered.', 'Offer "I went to Mombasa." beside "We do not talk with food in our mouths at home." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep to the idea in the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T3_INTENSIVE_READING_NA.RELATE_TO_LIFE.M5_RL_CHANGES_TEXT', 'ENGL.G5.READIN.T3_INTENSIVE_READING_NA.RELATE_TO_LIFE', 'Changes what the text says to fit his or her life.', '{"question":"In the text, the boy said sorry. What did he do?","wrong_answer":"He ran away, like my brother does.","correct_answer":"He said sorry."}'::jsonb, 'Own experience overwrites the text.', 'Offer "He ran away, like my brother does." beside "He said sorry." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep what the text says, then compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T3_INTENSIVE_READING_NA.VISUALISE.M5_VI_ONE_WORD', 'ENGL.G5.READIN.T3_INTENSIVE_READING_NA.VISUALISE', 'Builds the picture from one word and misses the other details.', '{"question":"\"A small boy in a torn red shirt sat under a mango tree.\" Which picture?","wrong_answer":"a boy under a tree (any shirt)","correct_answer":"a small boy in a torn red shirt under a mango tree"}'::jsonb, 'The first strong word is taken.', 'Offer "a boy under a tree (any shirt)" beside "a small boy in a torn red shirt under a mango tree" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check every describing word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T3_INTENSIVE_READING_NA.VISUALISE.M5_VI_ADDS', 'ENGL.G5.READIN.T3_INTENSIVE_READING_NA.VISUALISE', 'Adds details the text does not give.', '{"question":"\"The market was crowded.\" Which detail is in the text?","wrong_answer":"it was raining","correct_answer":"many people"}'::jsonb, 'Imagination fills in what is not said.', 'Offer "it was raining" beside "many people" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Picture only what the words tell you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T3_INTENSIVE_READING_NA.VISUALISE.M5_VI_TIME_IGNORED', 'ENGL.G5.READIN.T3_INTENSIVE_READING_NA.VISUALISE', 'Ignores time words (night, morning) in the picture.', '{"question":"\"At night, the lamp lit the room.\" Which picture?","wrong_answer":"a sunny room","correct_answer":"a dark room with a lamp"}'::jsonb, 'Time words are not seen as describing.', 'Offer "a sunny room" beside "a dark room with a lamp" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Night and morning change the picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T3_INTENSIVE_READING_NA.VISUALISE.M5_VI_CHARACTER_MIX', 'ENGL.G5.READIN.T3_INTENSIVE_READING_NA.VISUALISE', 'Gives one character''s looks to another.', '{"question":"\"Juma was tall; his sister was short.\" Who is short?","wrong_answer":"Juma","correct_answer":"his sister"}'::jsonb, 'Two characters described close together.', 'Offer "Juma" beside "his sister" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match each describing word to its person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.TOO_TO.M_TOO_MISSING_TO', 'ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.TOO_TO', 'Leaves out "to" before the verb after too + adjective.', '{"question":"The bag was too heavy carry.","wrong_answer":"too heavy carry","correct_answer":"too heavy to carry"}'::jsonb, 'Kiswahili joins the verb with ku-, so a separate small word feels unnecessary.', 'A sentence with "to" missing.', 'Say the pattern: too + adjective + TO + verb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.TOO_TO.M_TOO_FOR_TO', 'ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.TOO_TO', 'Writes "for to" or "for" before a verb.', '{"question":"The soup was too hot for to drink.","wrong_answer":"too hot for to drink","correct_answer":"too hot to drink"}'::jsonb, 'Mixes the pattern too ... for (person) with too ... to (verb).', 'for to among the options.', 'Use for before a person (for me) and to before a verb (to drink).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.TOO_TO.M_TOO_THAT', 'ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.TOO_TO', 'Uses a that-clause after too, as in "too tired that he slept".', '{"question":"Otieno was too tired that he slept.","wrong_answer":"too tired that","correct_answer":"too tired to stay awake"}'::jsonb, 'Confuses too with so ... that.', 'A that-clause after too.', 'So tired THAT he slept. Too tired TO stay awake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.TOO_TO.M_TOO_FOR_VERB', 'ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.TOO_TO', 'Puts the person after to instead of for (too heavy to me).', '{"question":"The box is too heavy to me to lift.","wrong_answer":"too heavy to me","correct_answer":"too heavy for me"}'::jsonb, 'Uses to for every person in a sentence.', 'to + person among the options.', 'Before a person, say for: for me, for him.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.MUST_SHOULD_ADVERB.M_MODAL_TO', 'ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.MUST_SHOULD_ADVERB', 'Writes "to" after must or should.', '{"question":"You should to wash your hands.","wrong_answer":"should to wash","correct_answer":"should wash"}'::jsonb, 'Copies the pattern want to, need to, have to.', 'must/should + to among the options.', 'Must and should go straight to the verb, with no to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.MUST_SHOULD_ADVERB.M_MODAL_VERB_FORM', 'ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.MUST_SHOULD_ADVERB', 'Puts -s, -ed or -ing on the verb after must or should.', '{"question":"Children must walking carefully.","wrong_answer":"must walking","correct_answer":"must walk"}'::jsonb, 'Thinks every verb must change for tense or number.', 'must/should + verb form among the options.', 'After must and should the verb never changes: must walk, she should walk.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.MUST_SHOULD_ADVERB.M_MODAL_ADJECTIVE', 'ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.MUST_SHOULD_ADVERB', 'Uses an adjective where an adverb is needed (speak polite).', '{"question":"You must speak polite to elders.","wrong_answer":"speak polite","correct_answer":"speak politely"}'::jsonb, 'Kiswahili uses one word for both (kwa adabu / mpole), so the -ly change is not obvious.', 'The adjective in place of the adverb.', 'Ask: how must you speak? Politely. The word describes the verb, so it ends in -ly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.MUST_SHOULD_ADVERB.M_MODAL_STRENGTH', 'ENGL.G5.GRAMMA.T3_LANGUAGE_PATTERN.MUST_SHOULD_ADVERB', 'Uses should for a strict rule, or must for a gentle suggestion.', '{"question":"Passengers ___ wear a seat belt. It is the law.","wrong_answer":"should","correct_answer":"must"}'::jsonb, 'Treats must and should as the same word.', 'A rule or law next to should, and advice next to must.', 'Must is for rules and strong duty. Should is for advice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T3_MECHANICS_OF_WRITING.CURSIVE.M5_CU_PRINT_MIX', 'ENGL.G5.WRITIN.T3_MECHANICS_OF_WRITING.CURSIVE', 'Mixes print and joined letters in one word.', '{"question":"Write \"happy\" in cursive.","wrong_answer":"h-a joined, p p y printed","correct_answer":"all letters joined"}'::jsonb, 'The joins for some letters are not learnt.', 'Offer "h-a joined, p p y printed" beside "all letters joined" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Join every letter in the word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T3_MECHANICS_OF_WRITING.CURSIVE.M5_CU_SLANT', 'ENGL.G5.WRITIN.T3_MECHANICS_OF_WRITING.CURSIVE', 'Slants letters in different directions.', '{"question":"Copy a sentence in cursive.","wrong_answer":"letters lean left and right","correct_answer":"all letters lean the same way"}'::jsonb, 'The paper is turned or the grip changes.', 'Offer "letters lean left and right" beside "all letters lean the same way" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the paper still and lean all letters the same way.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T3_MECHANICS_OF_WRITING.CURSIVE.M5_CU_JOIN_WORDS', 'ENGL.G5.WRITIN.T3_MECHANICS_OF_WRITING.CURSIVE', 'Joins the last letter of one word to the next word.', '{"question":"Write \"we eat\" in cursive.","wrong_answer":"weeat","correct_answer":"we eat"}'::jsonb, 'Joining is overdone.', 'Offer "weeat" beside "we eat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Join letters inside a word only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T3_MECHANICS_OF_WRITING.CURSIVE.M5_CU_CANNOT_READ', 'ENGL.G5.WRITIN.T3_MECHANICS_OF_WRITING.CURSIVE', 'Cannot read text written in cursive.', '{"question":"Read the cursive note from the teacher.","wrong_answer":"cannot read it","correct_answer":"reads it"}'::jsonb, 'Only print has been read before.', 'Offer "cannot read it" beside "reads it" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Practise reading joined writing every day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.ROAD_SAFETY_WORDS.M_VOC_ROAD_NEAR', 'ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.ROAD_SAFETY_WORDS', 'Chooses a road word with a related meaning that does not fit.', '{"question":"A person who walks on the road is a ___.","wrong_answer":"passenger","correct_answer":"pedestrian"}'::jsonb, 'Knows the topic words but not their exact meaning.', 'Two road words that are close in meaning.', 'Pedestrian walks. Passenger rides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.ROAD_SAFETY_WORDS.M_VOC_ROAD_SOUND', 'ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.ROAD_SAFETY_WORDS', 'Chooses a word that sounds like the right one.', '{"question":"Cross the road at the zebra ___.","wrong_answer":"crosswalk","correct_answer":"crossing"}'::jsonb, 'Uses a word met elsewhere.', 'A word from American English or one with a similar sound.', 'Say the whole phrase: zebra crossing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS.M5_WS_NOUN_VERB_SAME', 'ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'Stresses a noun and its verb the same way.', '{"question":"Say \"record\" as a verb: Please ___ the song.","wrong_answer":"REcord","correct_answer":"reCORD"}'::jsonb, 'The stress-meaning link is not known.', 'Offer "REcord" beside "reCORD" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Nouns are often strong at the start, verbs at the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS.M5_WS_EQUAL', 'ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'Gives every syllable equal stress.', '{"question":"Say: pedestrian","wrong_answer":"PE-DES-TRI-AN","correct_answer":"pe-DES-tri-an"}'::jsonb, 'Syllable-timed home languages give each syllable equal weight.', 'Offer "PE-DES-TRI-AN" beside "pe-DES-tri-an" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One strong syllable; the rest are short.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS.M5_WS_PENULT', 'ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'Puts the stress on the next-to-last syllable.', '{"question":"Say: accident","wrong_answer":"ac-CI-dent","correct_answer":"AC-ci-dent"}'::jsonb, 'Kiswahili stresses the next-to-last syllable.', 'Offer "ac-CI-dent" beside "AC-ci-dent" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Clap it: AC-ci-dent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS.M5_WS_PRESENT', 'ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'Says present (a gift) like present (to give).', '{"question":"Mum gave me a ___ (gift).","wrong_answer":"preSENT","correct_answer":"PREsent"}'::jsonb, 'One stress pattern is used for both words.', 'Offer "preSENT" beside "PREsent" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A PREsent is a gift; to preSENT is to give or show.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.ROAD_SAFETY_WORDS.M5_VOC_ZEBRA', 'ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.ROAD_SAFETY_WORDS', 'Thinks a zebra crossing is for animals.', '{"question":"A zebra crossing is ...","wrong_answer":"where zebras cross","correct_answer":"striped lines where people cross the road"}'::jsonb, 'The literal word meaning.', 'Offer "where zebras cross" beside "striped lines where people cross the road" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'It is named for its stripes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.ROAD_SAFETY_WORDS.M5_VOC_SPEED_BUMP', 'ENGL.G5.LISTEN.T4_PRONUNCIATION_AND_VO.ROAD_SAFETY_WORDS', 'Mixes up a speed bump and a roundabout.', '{"question":"A raised strip that slows cars is a ...","wrong_answer":"roundabout","correct_answer":"speed bump"}'::jsonb, 'Both slow traffic.', 'Offer "roundabout" beside "speed bump" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A bump is raised; a roundabout is a circle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T4_INTENSIVE_READING_CO.READ_VISUALS.M5_RV_TYPE_MIX', 'ENGL.G5.READIN.T4_INTENSIVE_READING_CO.READ_VISUALS', 'Calls a map a poster or a chart a picture.', '{"question":"A drawing with roads and a key is a ...","wrong_answer":"poster","correct_answer":"map"}'::jsonb, 'Visuals are named by topic, not by type.', 'Offer "poster" beside "map" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A map shows places and has a key.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T4_INTENSIVE_READING_CO.READ_VISUALS.M5_RV_ONE_DETAIL', 'ENGL.G5.READIN.T4_INTENSIVE_READING_CO.READ_VISUALS', 'Predicts from one detail and ignores the title.', '{"question":"A poster shows a car and the title \"Stop. Look. Cross.\" The text will be about ...","wrong_answer":"cars for sale","correct_answer":"crossing the road safely"}'::jsonb, 'The biggest picture is taken as the topic.', 'Offer "cars for sale" beside "crossing the road safely" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the title and words as well as the picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T4_INTENSIVE_READING_CO.READ_VISUALS.M5_RV_COLOUR_JUDGE', 'ENGL.G5.READIN.T4_INTENSIVE_READING_CO.READ_VISUALS', 'Judges a visual by how colourful it is, not by its message.', '{"question":"Which road safety poster is better?","wrong_answer":"the brightest one","correct_answer":"the one whose message is clear"}'::jsonb, 'Attractiveness is mistaken for effectiveness.', 'Offer "the brightest one" beside "the one whose message is clear" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask: does it tell people what to do?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T4_INTENSIVE_READING_CO.READ_VISUALS.M5_RV_MNEMONIC', 'ENGL.G5.READIN.T4_INTENSIVE_READING_CO.READ_VISUALS', 'Does not know a mnemonic is a memory aid.', '{"question":"Stop, Look, Listen, Think is a ...","wrong_answer":"poem","correct_answer":"mnemonic to remember road safety steps"}'::jsonb, 'The word mnemonic is new.', 'Offer "poem" beside "mnemonic to remember road safety steps" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A mnemonic helps you remember a list.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T4_WORD_CLASS_POSSESSIV.POSSESSIVES.M_POSS_DET_FOR_PRONOUN', 'ENGL.G5.GRAMMA.T4_WORD_CLASS_POSSESSIV.POSSESSIVES', 'Uses my, your, her, our or their when nothing follows the word.', '{"question":"That cup is ___.","wrong_answer":"my","correct_answer":"mine"}'::jsonb, 'Does not see that my needs a noun after it.', 'A gap at the end of the sentence.', 'My bag, but the bag is mine. If no noun follows, use mine, yours, hers, ours or theirs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T4_WORD_CLASS_POSSESSIV.POSSESSIVES.M_POSS_PRONOUN_BEFORE_NOUN', 'ENGL.G5.GRAMMA.T4_WORD_CLASS_POSSESSIV.POSSESSIVES', 'Uses mine, yours, ours or theirs in front of a noun.', '{"question":"Is this ___ book?","wrong_answer":"yours","correct_answer":"your"}'::jsonb, 'Learns the stand-alone forms and uses them everywhere.', 'A noun straight after the gap.', 'If a noun comes next, use my, your, her, our or their.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T4_WORD_CLASS_POSSESSIV.POSSESSIVES.M_POSS_APOSTROPHE', 'ENGL.G5.GRAMMA.T4_WORD_CLASS_POSSESSIV.POSSESSIVES', 'Writes her''s, our''s, their''s or your''s.', '{"question":"The blue pen is her''s.","wrong_answer":"her''s","correct_answer":"hers"}'::jsonb, 'Copies the apostrophe from Juma''s and Amina''s.', 'her''s, our''s, their''s among the options.', 'Possessive pronouns never take an apostrophe: hers, ours, theirs, yours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T4_WORD_CLASS_POSSESSIV.POSSESSIVES.M_POSS_WRONG_PERSON', 'ENGL.G5.GRAMMA.T4_WORD_CLASS_POSSESSIV.POSSESSIVES', 'Uses a possessive word for the wrong person (his for Mama).', '{"question":"Mama lost ___ keys.","wrong_answer":"his","correct_answer":"her"}'::jsonb, 'Does not link the possessive word to the owner.', 'A possessive for the wrong person.', 'Ask: whose keys? Mama is a woman, so her.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.LETTER_PARTS.M5_LP_OFFICIAL_WORDS', 'ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.LETTER_PARTS', 'Accepts official words in a friendly letter.', '{"question":"Is \"I am writing to inform you\" right for a letter to a cousin?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Official phrases seem more correct.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A friendly letter sounds like friendly talk.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.LETTER_PARTS.M5_LP_TWO_ADDRESSES', 'ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.LETTER_PARTS', 'Thinks a friendly letter has two addresses.', '{"question":"How many addresses in a friendly letter?","wrong_answer":"two","correct_answer":"one, the writer''s"}'::jsonb, 'Official letter format is mixed in.', 'Offer "two" beside "one, the writer''s" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Only your address, top right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.LETTER_PARTS.M5_LP_CLOSING_GREETING', 'ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.LETTER_PARTS', 'Mixes up the greeting and the closing.', '{"question":"Which is the closing?","wrong_answer":"Dear Wanjiku,","correct_answer":"Your loving friend,"}'::jsonb, 'Both are short lines with a comma.', 'Offer "Dear Wanjiku," beside "Your loving friend," in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Dear starts; Your ... ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.LETTER_PARTS.M5_LP_DATE_PLACE', 'ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.LETTER_PARTS', 'Puts the date in the body or leaves it out.', '{"question":"Where does the date go?","wrong_answer":"in the last paragraph","correct_answer":"under the address"}'::jsonb, 'The date is not seen as part of the layout.', 'Offer "in the last paragraph" beside "under the address" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Date under the address, top right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER.M5_FL_NO_PARAGRAPHS', 'ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER', 'Writes the body with no paragraphs.', '{"question":"How should the news be set out?","wrong_answer":"one block","correct_answer":"a paragraph for each piece of news"}'::jsonb, 'Paragraphing is skipped in letters.', 'Offer "one block" beside "a paragraph for each piece of news" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'New piece of news, new paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER.M5_FL_COLD_TONE', 'ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER', 'Writes in a cold, official tone.', '{"question":"Which opening suits a letter to a friend?","wrong_answer":"I hereby write to tell you","correct_answer":"How are you? I hope you are well."}'::jsonb, 'Official letters are copied.', 'Offer "I hereby write to tell you" beside "How are you? I hope you are well." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Write as you would talk to the friend.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER.M5_FL_NO_QUESTION', 'ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER', 'Writes only about himself or herself and asks nothing.', '{"question":"How can you show interest in your friend?","wrong_answer":"tell more about me","correct_answer":"ask how they are and about their news"}'::jsonb, 'The letter is seen as a report.', 'Offer "tell more about me" beside "ask how they are and about their news" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask your friend a question or two.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER.M5_FL_ABRUPT_END', 'ENGL.G5.WRITIN.T4_FUNCTIONAL_WRITING_F.FRIENDLY_LETTER', 'Ends suddenly with no closing line.', '{"question":"What comes before \"Your friend,\"?","wrong_answer":"nothing","correct_answer":"a closing line such as \"Write soon.\""}'::jsonb, 'The child stops when the news is done.', 'Offer "nothing" beside "a closing line such as "Write soon."" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'End with a line like Write soon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T5_LISTENING_COMPREHENS.EXPRESS_FEELINGS.M5_EF_FLAT', 'ENGL.G5.LISTEN.T5_LISTENING_COMPREHENS.EXPRESS_FEELINGS', 'Speaks with no feeling in the voice.', '{"question":"Tell the class about winning the race.","wrong_answer":"flat voice and still face","correct_answer":"excited voice, smile, open gestures"}'::jsonb, 'The child thinks speaking well means speaking quietly and still.', 'Offer "flat voice and still face" beside "excited voice, smile, open gestures" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Let your voice and face show how you felt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T5_LISTENING_COMPREHENS.EXPRESS_FEELINGS.M5_EF_WRONG_FEELING', 'ENGL.G5.LISTEN.T5_LISTENING_COMPREHENS.EXPRESS_FEELINGS', 'Shows a feeling that does not fit the words.', '{"question":"Read: \"Our goat died last night.\"","wrong_answer":"laughs while reading","correct_answer":"slow, sad voice"}'::jsonb, 'Nerves in front of the class come out as laughter.', 'Offer "laughs while reading" beside "slow, sad voice" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match your face to the words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T5_LISTENING_COMPREHENS.EXPRESS_FEELINGS.M5_EF_LISTENER_AWAY', 'ENGL.G5.LISTEN.T5_LISTENING_COMPREHENS.EXPRESS_FEELINGS', 'Looks away or plays while listening.', '{"question":"How do you show the speaker you are listening?","wrong_answer":"look at my desk and play with a pen","correct_answer":"face the speaker and nod"}'::jsonb, 'The child thinks listening is only with the ears.', 'Offer "look at my desk and play with a pen" beside "face the speaker and nod" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Face the speaker, nod and keep still.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T5_LISTENING_COMPREHENS.EXPRESS_FEELINGS.M5_EF_OVERACT', 'ENGL.G5.LISTEN.T5_LISTENING_COMPREHENS.EXPRESS_FEELINGS', 'Overacts so much the message is lost.', '{"question":"Tell how you felt at the national celebration.","wrong_answer":"shouts and jumps for every word","correct_answer":"proud voice with a few gestures"}'::jsonb, 'Acting is confused with expression.', 'Offer "shouts and jumps for every word" beside "proud voice with a few gestures" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A few gestures that fit are enough.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SCAN_SKIM.M_SCAN_READS_ALL', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SCAN_SKIM', 'Reads the whole text word by word instead of looking for the key word.', '{"question":"At what time does the bus leave?","wrong_answer":"a wrong time","correct_answer":"the time shown"}'::jsonb, 'Does not know that scanning means looking for one key word.', 'A time near the right time in the notice.', 'Look for the key word (bus), then read only that line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SCAN_SKIM.M_SCAN_WRONG_LINE', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SCAN_SKIM', 'Reads the nearest line and takes the detail from the wrong item.', '{"question":"Which day is the sports day?","wrong_answer":"a nearby day","correct_answer":"the correct day"}'::jsonb, 'Matches the number or day without matching the item.', 'The detail beside another event in the same notice.', 'Match the key word of the question to the right line first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SCAN_SKIM.M_SKIM_DETAIL_FOR_GIST', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SCAN_SKIM', 'Says a text is about one detail, not what it is mostly about.', '{"question":"What is the notice mainly about?","wrong_answer":"a detail","correct_answer":"the whole purpose"}'::jsonb, 'Stops after the first line.', 'A single detail offered as the topic.', 'Skim the title, first sentence and last sentence to find the gist.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SELECT_READING.M5_SR_COVER', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SELECT_READING', 'Chooses by the cover alone.', '{"question":"You want a story you will enjoy. What do you check?","wrong_answer":"the cover picture only","correct_answer":"the title, the blurb and one page"}'::jsonb, 'The cover is the most visible part.', 'Offer "the cover picture only" beside "the title, the blurb and one page" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the blurb and one page first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SELECT_READING.M5_SR_TOO_HARD', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SELECT_READING', 'Chooses a text far above his or her level to impress.', '{"question":"Which book is right to read alone?","wrong_answer":"a novel with many words I do not know","correct_answer":"a book where I know almost every word"}'::jsonb, 'Harder is thought to be better.', 'Offer "a novel with many words I do not know" beside "a book where I know almost every word" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'If more than five words on a page are new, it is too hard.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SELECT_READING.M5_SR_PURPOSE', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SELECT_READING', 'Chooses fiction when facts are needed.', '{"question":"You need facts on savings and banking. Which?","wrong_answer":"a story about a rich man","correct_answer":"a magazine article on saving"}'::jsonb, 'Any book on the topic seems to fit.', 'Offer "a story about a rich man" beside "a magazine article on saving" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Facts are in non-fiction.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SELECT_READING.M5_SR_DIGITAL_TRUST', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SELECT_READING', 'Trusts any website as a good source.', '{"question":"Which online text is better for a school project?","wrong_answer":"a stranger''s post with many likes","correct_answer":"a page from a known publisher or the KICD"}'::jsonb, 'Popularity is taken as reliability.', 'Offer "a stranger''s post with many likes" beside "a page from a known publisher or the KICD" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check who wrote it and why.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.INDEPENDENT_READING.M5_IR_SAME_BOOK', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.INDEPENDENT_READING', 'Rereads the same easy book again and again.', '{"question":"Your reading log shows the same book for three weeks. Is that wide reading?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Comfort with one book.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Try a new kind of text each week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.INDEPENDENT_READING.M5_IR_NO_RETELL', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.INDEPENDENT_READING', 'Reads to the end but cannot say what happened.', '{"question":"What was the magazine article about?","wrong_answer":"I finished it.","correct_answer":"It was about how a girl saved money for school."}'::jsonb, 'Reading is treated as a race.', 'Offer "I finished it." beside "It was about how a girl saved money for school." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stop after each page and think about it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.INDEPENDENT_READING.M5_IR_GIVES_UP', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.INDEPENDENT_READING', 'Gives up after one page.', '{"question":"The first page is slow. What do you do?","wrong_answer":"stop and choose nothing","correct_answer":"read two more pages before deciding"}'::jsonb, 'The child expects the start to be exciting.', 'Offer "stop and choose nothing" beside "read two more pages before deciding" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Give a book a few pages.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.INDEPENDENT_READING.M5_IR_FICTION_ONLY', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.INDEPENDENT_READING', 'Reads only stories, never non-fiction or poems.', '{"question":"Your log has only stories. What should you add?","wrong_answer":"more stories","correct_answer":"a poem and a magazine article"}'::jsonb, 'Stories feel like the only real reading.', 'Offer "more stories" beside "a poem and a magazine article" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read poems, articles and fact books too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SCAN_SKIM.M5_SKIM_EVERY_WORD', 'ENGL.G5.READIN.T5_EXTENSIVE_READING_FI.SCAN_SKIM', 'Reads every word when asked to skim.', '{"question":"Skim the article in one minute. What is it about?","wrong_answer":"only reached paragraph 1","correct_answer":"saving money in a bank"}'::jsonb, 'Skimming is not yet a separate skill.', 'Offer "only reached paragraph 1" beside "saving money in a bank" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the title, first lines and headings only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.COMPARATIVE_SUPERLATIVE.M_ADJ_DOUBLE_COMPARATIVE', 'ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.COMPARATIVE_SUPERLATIVE', 'Uses more and -er together, or most and -est together.', '{"question":"Kamau is more taller than Baraka.","wrong_answer":"more taller","correct_answer":"taller"}'::jsonb, 'Adds both signals to be sure the comparison is clear.', 'more/most together with -er/-est among the options.', 'One signal only: taller OR more careful.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.COMPARATIVE_SUPERLATIVE.M_ADJ_LONG_ER', 'ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.COMPARATIVE_SUPERLATIVE', 'Puts -er or -est on a long adjective (beautifuler).', '{"question":"This is the ___ story I have read.","wrong_answer":"interestingest","correct_answer":"most interesting"}'::jsonb, 'Applies the short-word rule to every adjective.', 'A long adjective with -er or -est among the options.', 'Short words take -er/-est. Long words take more/most.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.COMPARATIVE_SUPERLATIVE.M_ADJ_IRREGULAR', 'ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.COMPARATIVE_SUPERLATIVE', 'Writes gooder, more better, badder or worser.', '{"question":"This mango is ___ than that one.","wrong_answer":"gooder","correct_answer":"better"}'::jsonb, 'Applies the regular rule to good and bad.', 'gooder, more better, badder among the options.', 'Good, better, best. Bad, worse, worst. Learn these three words by heart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.COMPARATIVE_SUPERLATIVE.M_ADJ_THAN', 'ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.COMPARATIVE_SUPERLATIVE', 'Writes "that" or "then" instead of "than", or leaves it out.', '{"question":"Nyambura is taller then Mercy.","wrong_answer":"taller then","correct_answer":"taller than"}'::jsonb, 'Than and then sound alike in fast speech.', 'then or that in place of than.', 'Than compares two things. Then tells us what happened next.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.COMPARATIVE_SUPERLATIVE.M_ADJ_SUPERLATIVE_FOR_TWO', 'ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.COMPARATIVE_SUPERLATIVE', 'Uses the -est form to compare only two things, or the -er form for three or more.', '{"question":"Of the two sisters, Achieng is the ___.","wrong_answer":"tallest","correct_answer":"taller"}'::jsonb, 'Does not count how many things are compared.', 'A comparison of exactly two (or of many) things.', 'Two things: -er. Three or more: -est, with the.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.COMPARATIVE_SUPERLATIVE.M_ADJ_SPELLING', 'ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.COMPARATIVE_SUPERLATIVE', 'Spells the -er and -est forms wrongly (biger, happyer).', '{"question":"Mwende is ___ than her sister today.","wrong_answer":"happyer","correct_answer":"happier"}'::jsonb, 'Does not double the last letter or change y to i.', 'A misspelt -er or -est form among the options.', 'Big has one vowel and one consonant at the end: bigger. Happy ends in y: happier.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.ADJECTIVE_ORDER.M_ADJ_AFTER_NOUN', 'ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.ADJECTIVE_ORDER', 'Puts the adjective after the noun (a table big).', '{"question":"We bought ___.","wrong_answer":"a table big","correct_answer":"a big table"}'::jsonb, 'In Kiswahili the adjective follows the noun (meza kubwa).', 'The adjective after the noun among the options.', 'In English the describing word goes in front of the noun: big table, red cup.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.ADJECTIVE_ORDER.M_ADJ_ORDER_SHAPE_FIRST', 'ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.ADJECTIVE_ORDER', 'Puts shape or colour before size.', '{"question":"She wore ___ hat.","wrong_answer":"a red small","correct_answer":"a small red"}'::jsonb, 'Does not know the usual order of describing words.', 'Colour or shape before size.', 'Usual order: opinion, size, age, shape, colour, material. Size comes before colour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.ADJECTIVE_ORDER.M_ADJ_ORDER_AGE', 'ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.ADJECTIVE_ORDER', 'Puts age before size, or shape before age.', '{"question":"Grandfather sat on ___ stool.","wrong_answer":"an old big","correct_answer":"a big old"}'::jsonb, 'Orders the words by the order they come to mind.', 'Age before size.', 'Size first, then age, then shape: a big old round stool.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.ADJECTIVE_ORDER.M5_ADJ_ORDER_AND', 'ENGL.G5.GRAMMA.T5_WORD_CLASS_ADJECTIVE.ADJECTIVE_ORDER', 'Joins adjectives before a noun with and.', '{"question":"a ___ cooking pot (big, old)","wrong_answer":"big and old","correct_answer":"big old"}'::jsonb, 'And is used to join every pair.', 'Offer "big and old" beside "big old" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'No and between adjectives before a noun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_PARTS.M5_NP_INTRO_PROBLEM', 'ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_PARTS', 'Thinks the problem goes in the introduction.', '{"question":"Where does the main problem usually come?","wrong_answer":"the introduction","correct_answer":"the body"}'::jsonb, 'The child puts the exciting part first.', 'Offer "the introduction" beside "the body" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Introduction sets the scene; the problem comes in the body.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_PARTS.M5_NP_CONCLUSION_SUMMARY', 'ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_PARTS', 'Thinks the conclusion retells the whole story.', '{"question":"What does a conclusion do?","wrong_answer":"tell the story again","correct_answer":"say how it ended and what was learnt"}'::jsonb, 'Summaries from reading are mixed in.', 'Offer "tell the story again" beside "say how it ended and what was learnt" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The conclusion ends the story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_PARTS.M5_NP_SETTING_CHARACTER', 'ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_PARTS', 'Calls the setting a character.', '{"question":"\"The forest was dark and quiet.\" This sentence gives the ...","wrong_answer":"character","correct_answer":"setting"}'::jsonb, 'Places are described like people.', 'Offer "character" beside "setting" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Setting is where and when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_PARTS.M5_NP_TITLE_SENTENCE', 'ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_PARTS', 'Writes a full sentence as the title.', '{"question":"Better title?","wrong_answer":"The day that my goat got lost in the forest","correct_answer":"The Lost Goat"}'::jsonb, 'Titles are thought to tell everything.', 'Offer "The day that my goat got lost in the forest" beside "The Lost Goat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A title is short.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION.M5_NC_TENSE_SWITCH', 'ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION', 'Switches tense in the middle of the story.', '{"question":"Correct: Wanjiru opened the door and sees a snake.","wrong_answer":"opened ... sees","correct_answer":"opened ... saw"}'::jsonb, 'Present tense slips in at the exciting part.', 'Offer "opened ... sees" beside "opened ... saw" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the story in the past.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION.M5_NC_FORCED_PROVERB', 'ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION', 'Adds a proverb that does not fit the story.', '{"question":"Story about a careful boy who wins. Which proverb fits?","wrong_answer":"Too many cooks spoil the broth.","correct_answer":"Slow and steady wins the race."}'::jsonb, 'A proverb is added to get marks.', 'Offer "Too many cooks spoil the broth." beside "Slow and steady wins the race." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Choose a proverb whose lesson matches the story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION.M5_NC_NO_CLIMAX', 'ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION', 'Tells events with no problem or high point.', '{"question":"What makes the middle exciting?","wrong_answer":"more events","correct_answer":"a problem that builds up"}'::jsonb, 'The story is a list of events.', 'Offer "more events" beside "a problem that builds up" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Build to a problem, then solve it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION.M5_NC_DIALOGUE_UNPUNCTUATED', 'ENGL.G5.WRITIN.T5_CREATIVE_WRITING_NAR.NARRATIVE_COMPOSITION', 'Writes speech without quotation marks.', '{"question":"Write: Mum said come home","wrong_answer":"Mum said come home.","correct_answer":"Mum said, \"Come home.\""}'::jsonb, 'Speech is written as reported.', 'Offer "Mum said come home." beside "Mum said, "Come home."" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Put the spoken words in quotation marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION.M5_IN_WH_RISE', 'ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'Raises the voice at the end of WH questions.', '{"question":"Say: What is your job?","wrong_answer":"voice goes up at job","correct_answer":"voice falls at job"}'::jsonb, 'All questions are thought to go up.', 'Offer "voice goes up at job" beside "voice falls at job" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'WH questions fall at the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION.M5_IN_YESNO_FLAT', 'ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'Says yes or no questions with a flat tune.', '{"question":"Say: Is your mother a nurse?","wrong_answer":"flat, like a statement","correct_answer":"rising at nurse"}'::jsonb, 'Questions in the home language are marked by a word, not the tune.', 'Offer "flat, like a statement" beside "rising at nurse" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Lift the voice at the end of a yes or no question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION.M5_IN_SORT_BY_MARK', 'ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'Sorts a statement as rising because it contains a question word.', '{"question":"Rising or falling: I know where the clinic is.","wrong_answer":"rising","correct_answer":"falling"}'::jsonb, 'The question word is taken to mean a question.', 'Offer "rising" beside "falling" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'It is a statement: it falls.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION.M5_IN_STRESS_SMALL', 'ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'Stresses small words instead of the key word.', '{"question":"Say: My father is a FARMER.","wrong_answer":"MY father IS a farmer","correct_answer":"My father is a FARMER"}'::jsonb, 'Every word is given the same weight.', 'Offer "MY father IS a farmer" beside "My father is a FARMER" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stress the word that carries the news.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M5_PS_V_F', 'ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Says /f/ for /v/.', '{"question":"Say: van","wrong_answer":"fan","correct_answer":"van"}'::jsonb, 'No /v/ in the home language.', 'Offer "fan" beside "van" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Teeth on lip, voice on: vvv.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M5_PS_G_K', 'ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Says /k/ for /g/, especially at the end of a word.', '{"question":"Say: bag","wrong_answer":"back","correct_answer":"bag"}'::jsonb, 'Final voiced sounds are devoiced.', 'Offer "back" beside "bag" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the voice on to the end: bag.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M5_PS_Z_S', 'ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Says /s/ for /z/.', '{"question":"Say: buzz","wrong_answer":"bus","correct_answer":"buzz"}'::jsonb, 'Z is rare in the home language.', 'Offer "bus" beside "buzz" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Z buzzes like a bee; s hisses like a snake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M5_PS_SCHWA_FULL', 'ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Gives the weak /ə/ its full spelling vowel.', '{"question":"Say: banana","wrong_answer":"ba-NA-NA with three full a sounds","correct_answer":"buh-NAH-nuh"}'::jsonb, 'Reading by spelling: every a sounds the same.', 'Offer "ba-NA-NA with three full a sounds" beside "buh-NAH-nuh" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Weak syllables use the short uh sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M5_PS_EXTRA_VOWEL', 'ENGL.G5.LISTEN.T6_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Adds a vowel to a final consonant.', '{"question":"Say: book","wrong_answer":"booku","correct_answer":"book"}'::jsonb, 'Bantu syllables end in a vowel.', 'Offer "booku" beside "book" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stop cleanly on the last consonant.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.FEW_LITTLE.M_QUANT_FEW_UNCOUNTABLE', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.FEW_LITTLE', 'Uses few or a few with something that cannot be counted (few water).', '{"question":"There is ___ water in the jug.","wrong_answer":"a few","correct_answer":"a little"}'::jsonb, 'Does not ask whether the noun can be counted.', 'A noun such as water, milk, sugar or time.', 'Can you count it one by one? Books yes (few), water no (little).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.FEW_LITTLE.M_QUANT_LITTLE_COUNTABLE', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.FEW_LITTLE', 'Uses little or a little with something that can be counted (little books).', '{"question":"We have ___ chairs left.","wrong_answer":"a little","correct_answer":"a few"}'::jsonb, 'Learns "little" as the word for a small amount of anything.', 'A noun such as books, chairs, eggs or children.', 'Chairs can be counted, so few or a few.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.FEW_LITTLE.M_QUANT_NEGATIVE_POSITIVE', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.FEW_LITTLE', 'Does not tell few/little ("hardly any") from a few/a little ("some").', '{"question":"We have ___ eggs, so I can bake a small cake.","wrong_answer":"few","correct_answer":"a few"}'::jsonb, 'Treats the little word "a" as unimportant.', 'A sentence where the next part shows there is some (or hardly any).', '"A few" means enough to do something. "Few" means hardly any.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.FEW_LITTLE.M_QUANT_MUCH_MANY', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.FEW_LITTLE', 'Uses much with countable nouns or many with uncountable nouns.', '{"question":"There are too ___ cars on this road.","wrong_answer":"much","correct_answer":"many"}'::jsonb, 'Does not ask whether the noun can be counted.', 'much and many offered together.', 'Many goes with things you can count; much goes with things you cannot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.QUANTIFIERS_OTHER.M_QUANT_EACH_PLURAL', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.QUANTIFIERS_OTHER', 'Uses a plural verb after each.', '{"question":"Each of the girls ___ a bag.","wrong_answer":"have","correct_answer":"has"}'::jsonb, 'Hears "girls" and chooses the plural verb.', 'each + a plural noun and a plural verb among the options.', 'Each means one at a time, so the verb is singular: each girl has.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.QUANTIFIERS_OTHER.M_QUANT_ALL_SINGULAR', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.QUANTIFIERS_OTHER', 'Uses a singular noun after all (all the learner).', '{"question":"All the ___ were clapping.","wrong_answer":"learner","correct_answer":"learners"}'::jsonb, 'Does not match the noun to a word that means "every one of many".', 'all + a singular noun among the options.', 'All means many, so the noun is plural: all the learners.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.QUANTIFIERS_OTHER.M_QUANT_ENOUGH_POSITION', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.QUANTIFIERS_OTHER', 'Puts enough after the noun (water enough).', '{"question":"We do not have ___ for everyone.","wrong_answer":"food enough","correct_answer":"enough food"}'::jsonb, 'Kiswahili puts the describing word after the noun (chakula cha kutosha).', 'enough after the noun among the options.', 'Enough goes in front of a noun: enough food, enough chairs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.QUANTIFIERS_OTHER.M_QUANT_OF_THE_MISSING', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.QUANTIFIERS_OTHER', 'Writes most of learners or all of children, leaving out the.', '{"question":"___ walk to school.","wrong_answer":"Most of learners","correct_answer":"Most of the learners"}'::jsonb, 'Drops the small word the after of.', 'most of + a plural noun with no the.', 'After most of, all of and each of, add the or a pronoun: most of THE learners, all of THEM.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.QUANTIFIERS_OTHER.M_QUANT_LEAST_LESS', 'ENGL.G5.GRAMMA.T6_WORD_CLASS_DETERMINE.QUANTIFIERS_OTHER', 'Uses least for two things, or less where least is needed, or a lots of.', '{"question":"Of all the shops, this one sells the ___ sugar.","wrong_answer":"less","correct_answer":"least"}'::jsonb, 'Does not see the difference between comparing two and comparing many.', 'less and least offered together, or "a lots of".', 'Less compares two. Least compares three or more. We write a lot of or lots of, never a lots of.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T6_CREATIVE_WRITING_PIC.PICTORIAL_COMPOSITION.M5_PIC_LABELS', 'ENGL.G5.WRITIN.T6_CREATIVE_WRITING_PIC.PICTORIAL_COMPOSITION', 'Labels each picture instead of telling a story.', '{"question":"Picture 1 shows a nurse with a child.","wrong_answer":"A nurse. A child.","correct_answer":"Nurse Atieno gently weighed the crying baby."}'::jsonb, 'Lower-grade picture labelling.', 'Offer "A nurse. A child." beside "Nurse Atieno gently weighed the crying baby." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tell what happened, with names and actions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T6_CREATIVE_WRITING_PIC.PICTORIAL_COMPOSITION.M5_PIC_TOPIC_MISMATCH', 'ENGL.G5.WRITIN.T6_CREATIVE_WRITING_PIC.PICTORIAL_COMPOSITION', 'Chooses a topic that does not fit the pictures.', '{"question":"Pictures show a farmer selling milk. Topic?","wrong_answer":"My School","correct_answer":"A Day at the Dairy"}'::jsonb, 'The topic is chosen before looking.', 'Offer "My School" beside "A Day at the Dairy" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at all the pictures, then choose.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T6_CREATIVE_WRITING_PIC.PICTORIAL_COMPOSITION.M5_PIC_NO_LINKS', 'ENGL.G5.WRITIN.T6_CREATIVE_WRITING_PIC.PICTORIAL_COMPOSITION', 'Writes each picture as a separate piece with no links.', '{"question":"How do you join picture 2 to picture 3?","wrong_answer":"no link","correct_answer":"After that, ... ; Later, ..."}'::jsonb, 'Each picture is treated alone.', 'Offer "no link" beside "After that, ... ; Later, ..." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use time words to join the pictures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T6_CREATIVE_WRITING_PIC.PICTORIAL_COMPOSITION.M5_PIC_SKIP', 'ENGL.G5.WRITIN.T6_CREATIVE_WRITING_PIC.PICTORIAL_COMPOSITION', 'Leaves out a picture.', '{"question":"Five pictures: how many must the story cover?","wrong_answer":"four","correct_answer":"five"}'::jsonb, 'A hard picture is skipped.', 'Offer "four" beside "five" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tick every picture as you write.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US.FUTURE_WILL_SHALL.M_FUT_WILL_PAST', 'ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US.FUTURE_WILL_SHALL', 'Puts the past tense after will or shall (will went).', '{"question":"Tomorrow we will ___ to Nakuru.","wrong_answer":"went","correct_answer":"go"}'::jsonb, 'Thinks the verb must show tense after will.', 'will/shall + a past form among the options.', 'Will already says the future. The verb after it stays plain: will go.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US.FUTURE_WILL_SHALL.M_FUT_WILL_S', 'ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US.FUTURE_WILL_SHALL', 'Adds -s to the verb after will (will goes).', '{"question":"My mother will ___ us a story tonight.","wrong_answer":"tells","correct_answer":"tell"}'::jsonb, 'Matches the verb to he/she/it even after will.', 'will + a verb with -s among the options.', 'After will the verb never changes: will tell.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US.FUTURE_WILL_SHALL.M_FUT_WILL_ING', 'ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US.FUTURE_WILL_SHALL', 'Writes will going or will playing.', '{"question":"Next week the school will ___ a match.","wrong_answer":"playing","correct_answer":"play"}'::jsonb, 'Mixes the future with the -ing form heard in "I am going to".', 'will + an -ing verb among the options.', 'Will + plain verb. Or am going to + plain verb. Do not mix them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US.FUTURE_WILL_SHALL.M_FUT_PRESENT_FOR_FUTURE', 'ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US.FUTURE_WILL_SHALL', 'Uses the present tense for a future event with a time word (Tomorrow I go).', '{"question":"Tomorrow I ___ to Kisumu.","wrong_answer":"go","correct_answer":"will go"}'::jsonb, 'In speech the time word seems enough to show the future.', 'A future time word with a present tense verb among the options.', 'Tomorrow, next week and soon point to the future, so the verb needs will or shall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US.FUTURE_WILL_SHALL.M_FUT_DOUBLE_MODAL', 'ENGL.G5.GRAMMA.T7_TENSE_FUTURE_TIME_US.FUTURE_WILL_SHALL', 'Uses two helper verbs together (will shall go, will can).', '{"question":"We ___ visit Grandmother in December.","wrong_answer":"will shall","correct_answer":"shall"}'::jsonb, 'Combines two ways of speaking about the future.', 'will shall or will can among the options.', 'Choose one helper verb: will OR shall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.COMMAS.M_COMMA_LIST_MISSING', 'ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.COMMAS', 'Leaves out commas in a list.', '{"question":"Mama bought maize flour sugar and tea.","wrong_answer":"maize flour sugar and tea","correct_answer":"maize flour, sugar and tea"}'::jsonb, 'Does not see where one item ends.', 'A list written with no commas.', 'Put a comma after each item, except before and.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.COMMAS.M_COMMA_EVERYWHERE', 'ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.COMMAS', 'Puts a comma between the subject and the verb, or at every pause.', '{"question":"The children, played in the yard.","wrong_answer":"The children, played","correct_answer":"The children played"}'::jsonb, 'Writes a comma wherever the voice stops.', 'A comma that splits a subject from its verb.', 'A comma is not a breath mark. Do not split who from what they did.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.COMMAS.M_COMMA_AFTER_OPENING', 'ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.COMMAS', 'Leaves out the comma after an opening word or phrase (Yes I will; In the morning we left).', '{"question":"Yes I will come.","wrong_answer":"Yes I will come.","correct_answer":"Yes, I will come."}'::jsonb, 'Does not mark the end of an opening word.', 'A sentence that starts with yes, no, well, or a time phrase and has no comma.', 'After Yes, No, Well or an opening phrase, add a comma.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.COMMAS.M_COMMA_SPLICE', 'ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.COMMAS', 'Joins two full sentences with only a comma.', '{"question":"The bell rang, we ran outside.","wrong_answer":"The bell rang, we ran","correct_answer":"The bell rang, and we ran"}'::jsonb, 'Uses the comma as a full stop.', 'Two complete sentences with only a comma between them.', 'Use a full stop, or add and, but, so.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.DIRECT_SPEECH.M_QUOTE_MISSING', 'ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.DIRECT_SPEECH', 'Writes spoken words with no quotation marks.', '{"question":"Mother said Come and eat.","wrong_answer":"Mother said Come and eat.","correct_answer":"Mother said, \"Come and eat.\""}'::jsonb, 'Does not mark where speech begins and ends.', 'The spoken words with no marks.', 'Put double quotation marks around the exact words spoken.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.DIRECT_SPEECH.M_QUOTE_TOO_MUCH', 'ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.DIRECT_SPEECH', 'Puts the quotation marks round the words said and the speaker too.', '{"question":"\"Come and eat, said Mother.\"","wrong_answer":"\"Come and eat, said Mother.\"","correct_answer":"\"Come and eat,\" said Mother."}'::jsonb, 'Does not see where the speech stops.', 'Quotation marks that include said + name.', 'Only the spoken words go between the marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.DIRECT_SPEECH.M_QUOTE_PUNCTUATION_OUTSIDE', 'ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.DIRECT_SPEECH', 'Puts the comma, question mark or full stop outside the closing marks.', '{"question":"\"Where are you going\", asked Baba.","wrong_answer":"\"Where are you going\", asked Baba.","correct_answer":"\"Where are you going?\" asked Baba."}'::jsonb, 'Sees the end punctuation as part of the sentence, not of the speech.', 'A comma outside the closing marks, or a missing question mark.', 'The mark that ends the spoken words goes inside the quotation marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.DIRECT_SPEECH.M_QUOTE_NO_CAPITAL', 'ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.DIRECT_SPEECH', 'Starts the spoken words with a small letter.', '{"question":"Juma said, \"we are late.\"","wrong_answer":"Juma said, \"we are late.\"","correct_answer":"Juma said, \"We are late.\""}'::jsonb, 'Treats the speech as the middle of the sentence.', 'Spoken words that begin with a small letter.', 'The first word of the spoken words starts with a capital letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.DIRECT_SPEECH.M_QUOTE_SINGLE', 'ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.DIRECT_SPEECH', 'Uses single quotation marks.', '{"question":"Amina said, ''Thank you.''","wrong_answer":"single marks","correct_answer":"double marks"}'::jsonb, 'Single quotation marks are used in some books and the learner copies them.', 'A sentence with single marks.', 'The Grade 5 design asks for double quotation marks: " ".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.DIRECT_SPEECH.M_QUOTE_FULL_STOP_BEFORE_SAID', 'ENGL.G5.WRITIN.T7_MECHANICS_OF_WRITING.DIRECT_SPEECH', 'Ends the spoken words with a full stop when the speaker is named after them.', '{"question":"\"I am ready.\" said Otieno.","wrong_answer":"\"I am ready.\" said Otieno.","correct_answer":"\"I am ready,\" said Otieno."}'::jsonb, 'Thinks the spoken words are a complete sentence on their own.', 'A full stop before said + name.', 'When said + name follows, end the speech with a comma (or ? or !).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO.PROVERBS.M_PROV_LITERAL', 'ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO.PROVERBS', 'Takes the proverb literally.', '{"question":"What does \"A bird in the hand is worth two in the bush\" mean?","wrong_answer":"Birds are easy to catch.","correct_answer":"Be happy with what you have."}'::jsonb, 'Reads the words and not the lesson.', 'A literal reading among the options.', 'Ask: what lesson does the saying teach about people?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO.PROVERBS.M_PROV_NEAR_MEANING', 'ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO.PROVERBS', 'Chooses a lesson that is related but not the proverb''s.', '{"question":"Which situation fits \"Unity is strength\"?","wrong_answer":"a related lesson","correct_answer":"the right lesson"}'::jsonb, 'Remembers the general topic but not the exact lesson.', 'A situation about teamwork that fits another saying better.', 'Match the lesson, not the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO.PROVERBS.M_PROV_WORDS_MIXED', 'ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO.PROVERBS', 'Mixes the words of two proverbs.', '{"question":"Finish the proverb: A stitch in time saves ___.","wrong_answer":"ten","correct_answer":"nine"}'::jsonb, 'Remembers the shape and not the exact words.', 'A number or word from another proverb.', 'Say the proverb aloud three times and listen for the ending.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO.PROVERBS.M5_PROV_SITUATION', 'ENGL.G5.LISTEN.T8_PRONUNCIATION_AND_VO.PROVERBS', 'Uses a proverb in a situation it does not fit.', '{"question":"Which proverb fits a boy who saved a little each week?","wrong_answer":"Too many cooks spoil the broth.","correct_answer":"Little by little fills the measure."}'::jsonb, 'The proverb is known but not its use.', 'Offer "Too many cooks spoil the broth." beside "Little by little fills the measure." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match the lesson to the situation.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T8_FLUENCY_IN_READING.READ_FLUENTLY.M5_RF_WORD_BY_WORD', 'ENGL.G5.READIN.T8_FLUENCY_IN_READING.READ_FLUENTLY', 'Reads word by word.', '{"question":"Read: Coffee and tea are cash crops in Kenya.","wrong_answer":"Coffee. and. tea. are.","correct_answer":"Coffee and tea / are cash crops / in Kenya."}'::jsonb, 'Each word takes all the attention.', 'Offer "Coffee. and. tea. are." beside "Coffee and tea / are cash crops / in Kenya." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read in groups of words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T8_FLUENCY_IN_READING.READ_FLUENTLY.M5_RF_NO_PAUSE', 'ENGL.G5.READIN.T8_FLUENCY_IN_READING.READ_FLUENTLY', 'Reads through commas and full stops.', '{"question":"Read: Farmers grow tea, coffee and sugarcane. They sell them.","wrong_answer":"no pauses at all","correct_answer":"short pause at the comma, longer at the full stop"}'::jsonb, 'Punctuation is not linked to the voice.', 'Offer "no pauses at all" beside "short pause at the comma, longer at the full stop" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Short pause at a comma, longer at a full stop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T8_FLUENCY_IN_READING.READ_FLUENTLY.M5_RF_GUESS_FIRST_LETTER', 'ENGL.G5.READIN.T8_FLUENCY_IN_READING.READ_FLUENTLY', 'Guesses a word from its first letter.', '{"question":"Read: The farmer harvested the crop.","wrong_answer":"The farmer harmed the crop.","correct_answer":"The farmer harvested the crop."}'::jsonb, 'The child guesses quickly to keep speed.', 'Offer "The farmer harmed the crop." beside "The farmer harvested the crop." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at the whole word; check it makes sense.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T8_FLUENCY_IN_READING.READ_FLUENTLY.M5_RF_NO_EXPRESSION', 'ENGL.G5.READIN.T8_FLUENCY_IN_READING.READ_FLUENTLY', 'Reads speech and questions in a flat voice.', '{"question":"Read: \"Is the tea ready?\" asked Mama.","wrong_answer":"flat","correct_answer":"questioning tone"}'::jsonb, 'The voice is not used to show meaning.', 'Offer "flat" beside "questioning tone" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Let your voice ask the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T8_SENTENCES.QUESTION_TAGS.M_TAG_INVARIABLE', 'ENGL.G5.GRAMMA.T8_SENTENCES.QUESTION_TAGS', 'Uses "isn''t it?" after every statement.', '{"question":"You are coming to the party, ___?","wrong_answer":"isn''t it","correct_answer":"aren''t you"}'::jsonb, 'Treats the tag as one fixed phrase.', 'isn''t it offered after a statement with you, they, we or a different helper verb.', 'Repeat the helper verb from the statement, then the pronoun: are you coming, ... aren''t you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T8_SENTENCES.QUESTION_TAGS.M_TAG_SAME_SIGN', 'ENGL.G5.GRAMMA.T8_SENTENCES.QUESTION_TAGS', 'Uses a tag with the same sign as the statement (He is tall, is he?).', '{"question":"Mwangi plays well, ___?","wrong_answer":"does he","correct_answer":"doesn''t he"}'::jsonb, 'Does not know that the tag reverses positive and negative.', 'A tag with the same sign as the statement.', 'A positive statement takes a negative tag. A negative statement takes a positive tag.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T8_SENTENCES.QUESTION_TAGS.M_TAG_WRONG_HELPER', 'ENGL.G5.GRAMMA.T8_SENTENCES.QUESTION_TAGS', 'Uses a different helper verb in the tag (She likes tea, isn''t she?).', '{"question":"She likes tea, ___?","wrong_answer":"isn''t she","correct_answer":"doesn''t she"}'::jsonb, 'Does not link the tag to the verb in the statement.', 'A tag with a helper verb that is not in the statement.', 'If the statement has likes, the tag uses does. If it has is, the tag uses is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T8_SENTENCES.QUESTION_TAGS.M_TAG_NOUN_FOR_PRONOUN', 'ENGL.G5.GRAMMA.T8_SENTENCES.QUESTION_TAGS', 'Repeats the noun in the tag instead of a pronoun.', '{"question":"Baraka is a good footballer, ___?","wrong_answer":"isn''t Baraka","correct_answer":"isn''t he"}'::jsonb, 'Copies the subject word for word.', 'A noun inside the tag.', 'The tag uses a short word for the person: he, she, it, they.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T8_SENTENCES.QUESTION_TAGS.M_TAG_FULL_FORM', 'ENGL.G5.GRAMMA.T8_SENTENCES.QUESTION_TAGS', 'Writes the tag in full (is not he) or in the wrong order (he isn''t).', '{"question":"The bus is late, ___?","wrong_answer":"is not it","correct_answer":"isn''t it"}'::jsonb, 'Does not know the tag turns the helper verb in front of the pronoun and is said short.', 'A tag written in full or in statement order.', 'Say it the way people speak: isn''t it, doesn''t she. The helper verb comes first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T8_CREATIVE_WRITING.SIMILES.M_SIM_STATEMENT', 'ENGL.G5.WRITIN.T8_CREATIVE_WRITING.SIMILES', 'Takes any description for a simile.', '{"question":"Which sentence is a simile?","wrong_answer":"He is very strong.","correct_answer":"He is as strong as an ox."}'::jsonb, 'Does not look for like or as.', 'A plain description beside a comparison.', 'A simile compares two different things using like or as.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T8_CREATIVE_WRITING.SIMILES.M_SIM_METAPHOR', 'ENGL.G5.WRITIN.T8_CREATIVE_WRITING.SIMILES', 'Takes a metaphor (without like or as) for a simile.', '{"question":"Which sentence is a simile?","wrong_answer":"He is a lion.","correct_answer":"He is as brave as a lion."}'::jsonb, 'Sees a comparison and does not check the joining word.', 'A metaphor beside a simile.', 'A simile has like or as. A metaphor says one thing IS another.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T8_CREATIVE_WRITING.SIMILES.M_SIM_WRONG_COMPARISON', 'ENGL.G5.WRITIN.T8_CREATIVE_WRITING.SIMILES', 'Completes a simile with a word that does not fit the quality.', '{"question":"As busy as a ___.","wrong_answer":"tortoise","correct_answer":"bee"}'::jsonb, 'Does not match the animal to the quality.', 'An animal known for a different quality.', 'Which animal or thing is famous for this quality?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T8_CREATIVE_WRITING.SIMILES.M5_SIM_LIKE_AS_MIX', 'ENGL.G5.WRITIN.T8_CREATIVE_WRITING.SIMILES', 'Mixes as ... as with like in one simile.', '{"question":"Complete: as strong ___ an ox","wrong_answer":"like","correct_answer":"as"}'::jsonb, 'Two simile patterns are mixed.', 'Offer "like" beside "as" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'As ... as, or like: not both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO.SPEAK_FLUENTLY.M5_SF_READ_NOTES', 'ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO.SPEAK_FLUENTLY', 'Reads the whole talk from paper without looking up.', '{"question":"Present your talk on diseases.","wrong_answer":"reads every word with head down","correct_answer":"looks at the class, glances at notes"}'::jsonb, 'The child is afraid of forgetting.', 'Offer "reads every word with head down" beside "looks at the class, glances at notes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Write key words only; look up and talk.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO.SPEAK_FLUENTLY.M5_SF_FILLERS', 'ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO.SPEAK_FLUENTLY', 'Fills pauses with eeh, aah or "like".', '{"question":"Talk about hand washing.","wrong_answer":"Eeh, we should, aah, wash ...","correct_answer":"We should wash our hands with soap."}'::jsonb, 'Searching for words aloud.', 'Offer "Eeh, we should, aah, wash ..." beside "We should wash our hands with soap." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Pause silently instead.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO.SPEAK_FLUENTLY.M5_SF_MONOTONE_FAST', 'ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO.SPEAK_FLUENTLY', 'Rushes in one tone to finish quickly.', '{"question":"Present your two-minute talk.","wrong_answer":"finishes in thirty seconds","correct_answer":"about two minutes at a steady pace"}'::jsonb, 'Nerves make the child rush.', 'Offer "finishes in thirty seconds" beside "about two minutes at a steady pace" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Slow down and pause after each point.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO.SPEAK_FLUENTLY.M5_SF_STOPS', 'ENGL.G5.LISTEN.T9_SPEAKING_FLUENCY_PRO.SPEAK_FLUENTLY', 'Stops and starts again when a word is wrong.', '{"question":"Talk about your favourite game.","wrong_answer":"I play, no, I played, no ...","correct_answer":"I play football every evening."}'::jsonb, 'Fear of mistakes.', 'Offer "I play, no, I played, no ..." beside "I play football every evening." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'If you slip, correct it once and go on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T9_INTENSIVE_READING_DE.MAIN_IDEA.M_MAIN_DETAIL', 'ENGL.G5.READIN.T9_INTENSIVE_READING_DE.MAIN_IDEA', 'Picks one detail as the main idea.', '{"question":"What is the main idea of the paragraph?","wrong_answer":"a single detail","correct_answer":"the whole idea"}'::jsonb, 'Chooses the sentence that was easiest to find.', 'A true detail from the paragraph.', 'The main idea covers the whole paragraph. A detail covers only one part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T9_INTENSIVE_READING_DE.MAIN_IDEA.M_MAIN_TOO_BROAD', 'ENGL.G5.READIN.T9_INTENSIVE_READING_DE.MAIN_IDEA', 'Picks a statement that is too wide for the paragraph.', '{"question":"What is the main idea of the paragraph?","wrong_answer":"a broad statement","correct_answer":"a fitting statement"}'::jsonb, 'Chooses a big idea the paragraph only touches.', 'A statement about the whole subject, bigger than the paragraph.', 'The main idea fits this paragraph, not the whole topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T9_INTENSIVE_READING_DE.MAIN_IDEA.M_MAIN_NOT_IN_TEXT', 'ENGL.G5.READIN.T9_INTENSIVE_READING_DE.MAIN_IDEA', 'Picks an idea that the paragraph does not discuss.', '{"question":"Which title best fits the paragraph?","wrong_answer":"an unrelated idea","correct_answer":"a fitting title"}'::jsonb, 'Chooses from background knowledge.', 'An idea on the same subject but not in the paragraph.', 'Check that the title matches what the paragraph says.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T9_INTENSIVE_READING_DE.SUMMARISE.M_SUM_TOO_MUCH_DETAIL', 'ENGL.G5.READIN.T9_INTENSIVE_READING_DE.SUMMARISE', 'Chooses a summary that retells every detail.', '{"question":"Which is the best summary?","wrong_answer":"a long retelling","correct_answer":"a short summary"}'::jsonb, 'Believes a longer answer is better.', 'A summary almost as long as the passage.', 'A summary is shorter and keeps only the main points.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T9_INTENSIVE_READING_DE.SUMMARISE.M_SUM_MISSING_MAIN', 'ENGL.G5.READIN.T9_INTENSIVE_READING_DE.SUMMARISE', 'Chooses a summary that leaves out a main point.', '{"question":"Which is the best summary?","wrong_answer":"a summary missing a main point","correct_answer":"a complete summary"}'::jsonb, 'Takes the first half of the passage only.', 'A summary that stops half way.', 'Check that every main point is in your summary.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T9_INTENSIVE_READING_DE.SUMMARISE.M_SUM_OPINION', 'ENGL.G5.READIN.T9_INTENSIVE_READING_DE.SUMMARISE', 'Adds an opinion or an idea that is not in the passage.', '{"question":"Which is the best summary?","wrong_answer":"a summary with an opinion","correct_answer":"a summary of the passage only"}'::jsonb, 'Adds what he or she thinks.', 'A summary with a judging word such as best, silly, lazy.', 'A summary tells what the passage says, not what you think.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T9_INTENSIVE_READING_DE.SUMMARISE.M_SUM_CUTS_MAIN', 'ENGL.G5.READIN.T9_INTENSIVE_READING_DE.SUMMARISE', 'Leaves out a main point and keeps a small detail.', '{"question":"Which sentence is a small detail that a summary can leave out?","wrong_answer":"a main point","correct_answer":"a small detail"}'::jsonb, 'Cannot tell main points from details.', 'A main point offered as the one to leave out.', 'Main points say what happens or what the text is about. Details add colour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.READIN.T9_INTENSIVE_READING_DE.MAIN_IDEA.M5_MAIN_FIRST_SENTENCE', 'ENGL.G5.READIN.T9_INTENSIVE_READING_DE.MAIN_IDEA', 'Always takes the first sentence as the main idea.', '{"question":"A paragraph starts with a question and ends with its point. Main idea?","wrong_answer":"the question","correct_answer":"the point at the end"}'::jsonb, 'The topic sentence is thought to be always first.', 'Offer "the question" beside "the point at the end" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask what the whole paragraph is about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.ADVERBS.M_ADV_ADJECTIVE_FOR_ADVERB', 'ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.ADVERBS', 'Uses an adjective after the verb (runs quick, speaks soft).', '{"question":"The boy ran ___ to school.","wrong_answer":"quick","correct_answer":"quickly"}'::jsonb, 'Kiswahili uses one word for both (haraka).', 'The adjective form among the options after a verb.', 'Ask: how did he run? The word describes the verb, so add -ly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.ADVERBS.M_ADV_GOOD_WELL', 'ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.ADVERBS', 'Uses good where well is needed (sings good).', '{"question":"Akinyi sings very ___.","wrong_answer":"good","correct_answer":"well"}'::jsonb, 'Treats good as the adverb of well.', 'good among the options after a verb.', 'Good describes a noun (a good singer). Well describes a verb (sings well).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.ADVERBS.M_ADV_HARD_HARDLY', 'ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.ADVERBS', 'Uses hardly for hard (works hardly).', '{"question":"The farmers work ___ in the shamba.","wrong_answer":"hardly","correct_answer":"hard"}'::jsonb, 'Adds -ly to every adjective to make an adverb.', 'hardly among the options.', 'Hard stays hard: works hard. Hardly means almost not at all.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.ADVERBS.M_ADV_TYPE_CONFUSION', 'ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.ADVERBS', 'Mixes up the kinds of adverb (time, frequency, place, manner).', '{"question":"In \"She often visits her aunt\", often tells us ___.","wrong_answer":"when (time)","correct_answer":"how often (frequency)"}'::jsonb, 'Sees "when" in every adverb that is about time.', 'A frequency word offered with time as an option.', 'Frequency answers how often: always, never, often, sometimes. Time answers when: today, soon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.ADVERBS.M_ADV_POSITION', 'ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.ADVERBS', 'Puts the adverb of frequency in the wrong place (She is late always).', '{"question":"Wanjiru ___ late.","wrong_answer":"always is","correct_answer":"is always"}'::jsonb, 'Places the adverb at the end as in Kiswahili (huchelewa kila mara).', 'A frequency word at the end of the sentence among the options.', 'Frequency words usually go before the main verb, but after is, am, are.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.COULD_WOULD.M_MOD_CAN_FOR_COULD', 'ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.COULD_WOULD', 'Uses can to talk about the past.', '{"question":"When I was five, I ___ climb trees.","wrong_answer":"can","correct_answer":"could"}'::jsonb, 'Does not change can for the past.', 'can in a sentence that begins with a past time.', 'Can is now. Could is the past of can.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.COULD_WOULD.M_MOD_WILL_FOR_WOULD', 'ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.COULD_WOULD', 'Uses will for an imagined result (If I had money, I will buy).', '{"question":"If I had a bicycle, I ___ ride to school.","wrong_answer":"will","correct_answer":"would"}'::jsonb, 'Does not match the if-part in the past with would in the result.', 'will after an if-part in the past tense.', 'If + past tense, then would + verb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.COULD_WOULD.M_MOD_PAST_AFTER_MODAL', 'ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.COULD_WOULD', 'Puts a past tense after could or would (could went).', '{"question":"He said he could ___ us.","wrong_answer":"helped","correct_answer":"help"}'::jsonb, 'Thinks the past needs two past words.', 'could/would + a past form.', 'Could already shows the past. The verb after it stays plain: could help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.COULD_WOULD.M_MOD_HOW_MANY_ORDER', 'ENGL.G5.GRAMMA.T9_WORD_CLASS_ADVERBS.COULD_WOULD', 'Gets the order wrong in how many ... could/would questions.', '{"question":"___ eggs could you carry?","wrong_answer":"How could you many","correct_answer":"How many"}'::jsonb, 'Does not keep how many together.', 'How and many split apart.', 'Keep how many together, then could, then the person, then the verb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.APOSTROPHE.M_APOS_PLURAL', 'ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.APOSTROPHE', 'Puts an apostrophe in a plain plural (banana''s for sale).', '{"question":"Fresh ___ for sale.","wrong_answer":"banana''s","correct_answer":"bananas"}'::jsonb, 'Thinks every s needs an apostrophe.', 'An apostrophe in a plural with no owner.', 'An apostrophe shows belonging or missing letters, never just more than one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.APOSTROPHE.M_APOS_ITS', 'ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.APOSTROPHE', 'Mixes up its (belonging) and it''s (it is).', '{"question":"The dog wagged ___ tail.","wrong_answer":"it''s","correct_answer":"its"}'::jsonb, 'Both sound the same and both look as if they need an apostrophe.', 'its and it''s offered together.', 'Say it is. If it fits, it''s. If not, its.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.APOSTROPHE.M_APOS_MISSING_OWNER', 'ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.APOSTROPHE', 'Leaves out the apostrophe when something belongs to someone (Jumas bag).', '{"question":"This is ___ bag.","wrong_answer":"Jumas","correct_answer":"Juma''s"}'::jsonb, 'Does not mark belonging in writing.', 'A noun with s and no apostrophe where belonging is meant.', 'Add apostrophe and s to show belonging: Juma''s bag.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.APOSTROPHE.M_APOS_CONTRACTION', 'ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.APOSTROPHE', 'Leaves out the apostrophe in don''t or puts it in the wrong place (do''nt).', '{"question":"We ___ have school on Saturday.","wrong_answer":"dont","correct_answer":"don''t"}'::jsonb, 'Does not mark the missing letter.', 'dont or do''nt among the options.', 'The apostrophe sits where the letter is missing: do not becomes don''t.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.APOSTROPHE.M_APOS_PLURAL_OWNER', 'ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.APOSTROPHE', 'Puts the apostrophe before the s when the owners are plural (the girl''s room, for many girls), or the reverse.', '{"question":"The ___ room is next to ours. (many girls)","wrong_answer":"girl''s","correct_answer":"girls''"}'::jsonb, 'Does not ask if one or many own it.', 'girl''s and girls'' offered together.', 'One owner: ''s. Many owners ending in s: s''.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.EXCLAMATION_MARK.M_EXCL_FULL_STOP', 'ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.EXCLAMATION_MARK', 'Uses a full stop after a shout, a warning or a strong feeling.', '{"question":"Look out for the car.","wrong_answer":"Look out for the car.","correct_answer":"Look out for the car!"}'::jsonb, 'Treats every sentence the same.', 'A warning or a cry that ends in a full stop.', 'A shout, a warning and strong surprise need !', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.EXCLAMATION_MARK.M_EXCL_OVERUSE', 'ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.EXCLAMATION_MARK', 'Uses an exclamation mark after calm, ordinary sentences.', '{"question":"We went to the market!","wrong_answer":"We went to the market!","correct_answer":"We went to the market."}'::jsonb, 'Thinks ! makes writing more exciting.', 'A calm statement ending in !', 'Keep ! for strong feeling. A calm statement ends in a full stop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.EXCLAMATION_MARK.M_EXCL_MANY', 'ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.EXCLAMATION_MARK', 'Writes more than one exclamation mark (!!!).', '{"question":"What a goal!!!","wrong_answer":"What a goal!!!","correct_answer":"What a goal!"}'::jsonb, 'Copies the style of messages on phones.', 'More than one ! at the end of a sentence.', 'One mark is enough in school writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.EXCLAMATION_MARK.M_EXCL_QUESTION', 'ENGL.G5.WRITIN.T9_MECHANICS_OF_WRITING.EXCLAMATION_MARK', 'Ends a real question with an exclamation mark.', '{"question":"Where is my pen!","wrong_answer":"Where is my pen!","correct_answer":"Where is my pen?"}'::jsonb, 'Writes a strong voice as ! even for a question.', 'A question that ends in !', 'A question that asks something ends with ?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.MOOD_FEELINGS.M_MOOD_OPPOSITE', 'ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.MOOD_FEELINGS', 'Names the opposite feeling from one cheerful or sad word.', '{"question":"Wafula laughed, but his hands shook. He felt ___.","wrong_answer":"happy","correct_answer":"nervous"}'::jsonb, 'Reads one word (laughed) and ignores the rest.', 'A mood that matches one word and not the others.', 'Check what the person does and says, not just one word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.MOOD_FEELINGS.M_MOOD_NAMED_NOT_SHOWN', 'ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.MOOD_FEELINGS', 'Names a feeling that is not supported by the lines.', '{"question":"How does Mama feel?","wrong_answer":"angry","correct_answer":"worried"}'::jsonb, 'Picks a strong feeling without evidence.', 'A strong feeling with no supporting words.', 'Find the words and actions that show the feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY.M5_IP_SHOUT', 'ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY', 'Shouts over the speaker.', '{"question":"Your friends are discussing a film and you want to add something.","wrong_answer":"shout \"Me! Me!\"","correct_answer":"Sorry to interrupt, but may I add something?"}'::jsonb, 'Excitement and no habit of waiting.', 'Offer "shout "Me! Me!"" beside "Sorry to interrupt, but may I add something?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Wait for a pause and ask.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY.M5_IP_NO_PAUSE', 'ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY', 'Interrupts in the middle of a sentence.', '{"question":"When should you interrupt?","wrong_answer":"any time","correct_answer":"at a pause"}'::jsonb, 'The child does not notice pauses.', 'Offer "any time" beside "at a pause" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Watch for the speaker to stop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY.M5_IP_TAKE_OVER', 'ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY', 'Interrupts and then takes over the conversation.', '{"question":"After you add your point, what next?","wrong_answer":"keep talking about my own idea","correct_answer":"let the speaker go on"}'::jsonb, 'The child does not give the turn back.', 'Offer "keep talking about my own idea" beside "let the speaker go on" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Make your point, then hand back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY.M5_IP_IMPOLITE_PHRASE', 'ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY', 'Uses an impolite phrase to interrupt.', '{"question":"Which is polite?","wrong_answer":"You are wrong, listen to me.","correct_answer":"Excuse me, may I say something?"}'::jsonb, 'Correcting is mixed with interrupting.', 'Offer "You are wrong, listen to me." beside "Excuse me, may I say something?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask permission before you speak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.MOOD_FEELINGS.M5_MOOD_ACTION_ONLY', 'ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.MOOD_FEELINGS', 'Names what happened instead of the mood.', '{"question":"What is the mood of the poem about a lonely night?","wrong_answer":"night","correct_answer":"lonely, sad"}'::jsonb, 'The topic is given instead of the feeling.', 'Offer "night" beside "lonely, sad" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Mood is a feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.MOOD_FEELINGS.M5_MOOD_ONE_LINE', 'ENGL.G5.LISTEN.T10_PRONUNCIATION_AND_VO.MOOD_FEELINGS', 'Takes the mood from one line and ignores the rest.', '{"question":"A choral verse starts sad and ends joyful. The mood at the end?","wrong_answer":"sad","correct_answer":"joyful"}'::jsonb, 'The first line sticks.', 'Offer "sad" beside "joyful" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Moods can change; read to the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS.M_CONJ_BECAUSE_FOR_BUT', 'ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS', 'Uses because where but (a contrast) is needed.', '{"question":"Ali is small, ___ he runs very fast.","wrong_answer":"because","correct_answer":"but"}'::jsonb, 'Joins two ideas without asking how they relate.', 'because/so offered where the second idea is a surprise.', 'Ask: is the second part a reason, a surprise or a choice?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS.M_CONJ_DOUBLE', 'ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS', 'Uses two joining words together (Because ..., so ...; Although ..., but ...).', '{"question":"Because it was raining, so we stayed home.","wrong_answer":"Because..., so...","correct_answer":"Because ... , we stayed home"}'::jsonb, 'Kiswahili uses two joining words (kwa sababu... kwa hivyo).', 'A sentence with both because and so.', 'One joining word per sentence. Because it rained, we stayed. Or: It rained, so we stayed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS.M_CONJ_OR_AND', 'ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS', 'Uses and where or (a choice) is needed.', '{"question":"Would you like tea ___ milk?","wrong_answer":"and","correct_answer":"or"}'::jsonb, 'Treats and as the only joining word.', 'and offered when two things are being chosen between.', 'A choice between two things uses or.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS.M_CONJ_SINCE_TIME', 'ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS', 'Uses since only for time and misses its meaning of because.', '{"question":"We stayed indoors ___ it was raining.","wrong_answer":"since","correct_answer":"because"}'::jsonb, 'Learns only the time meaning of since.', 'Since as a reason offered or rejected.', 'Since can mean because. Since I was five means a time. Since it rained means a reason.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS.M_CONJ_ALSO_JOINING', 'ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS', 'Uses also as if it joined two words (tea also coffee).', '{"question":"We bought sugar ___ rice.","wrong_answer":"also","correct_answer":"and"}'::jsonb, 'Thinks also is another way to say and.', 'also between two nouns.', 'Also adds an idea in a new sentence or after the verb. And joins two words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS.M_CONJ_WRONG_MEANING', 'ENGL.G5.GRAMMA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS', 'Chooses a joining word that does not fit the meaning of the two parts.', '{"question":"We bought sugar ___ rice.","wrong_answer":"but","correct_answer":"and"}'::jsonb, 'Treats all joining words as the same.', 'A joining word whose meaning does not fit the two ideas.', 'Say the two parts and ask: do they add, contrast, give a reason or offer a choice?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIBE_FROM_TEXT.M5_DT_ACTION', 'ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIBE_FROM_TEXT', 'Gives an action instead of a description.', '{"question":"\"Grandma, kind and wrinkled, told stories.\" What is Grandma like?","wrong_answer":"told stories","correct_answer":"kind and wrinkled"}'::jsonb, 'What the person did is easier to find.', 'Offer "told stories" beside "kind and wrinkled" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Describing words tell what the person is like.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIBE_FROM_TEXT.M5_DT_OTHER_PERSON', 'ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIBE_FROM_TEXT', 'Gives the description of another person.', '{"question":"\"Otieno was tall; his friend was quiet.\" What is Otieno like?","wrong_answer":"quiet","correct_answer":"tall"}'::jsonb, 'Two descriptions near each other.', 'Offer "quiet" beside "tall" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match the words to the right person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIBE_FROM_TEXT.M5_DT_OWN_IDEA', 'ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIBE_FROM_TEXT', 'Describes from his or her own idea, not the text.', '{"question":"What is the park like in the text?","wrong_answer":"big and full of lions","correct_answer":"green, quiet and shady"}'::jsonb, 'The child uses general knowledge.', 'Offer "big and full of lions" beside "green, quiet and shady" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use the words from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIBE_FROM_TEXT.M5_DT_ONE_WORD', 'ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIBE_FROM_TEXT', 'Gives only one describing word when the text gives several.', '{"question":"\"The lake was wide, calm and blue.\" Describe the lake.","wrong_answer":"blue","correct_answer":"wide, calm and blue"}'::jsonb, 'The child stops at the first match.', 'Offer "blue" beside "wide, calm and blue" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Collect every describing word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION.M5_DC_STORY', 'ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION', 'Writes a story instead of a description.', '{"question":"Describe your favourite leisure place.","wrong_answer":"One day we went there and lost our ball.","correct_answer":"The park is green and quiet, with tall jacaranda trees."}'::jsonb, 'Narrative is the most practised.', 'Offer "One day we went there and lost our ball." beside "The park is green and quiet, with tall jacaranda trees." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Describe how it is, not what happened.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION.M5_DC_VAGUE', 'ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION', 'Uses vague words such as nice and good.', '{"question":"Improve: The swimming pool is nice.","wrong_answer":"The swimming pool is nice.","correct_answer":"The swimming pool is clear blue and cool."}'::jsonb, 'A small stock of adjectives.', 'Offer "The swimming pool is nice." beside "The swimming pool is clear blue and cool." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use exact words for each sense.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION.M5_DC_NO_ORDER', 'ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION', 'Describes in a jumbled order.', '{"question":"Which order is clearer?","wrong_answer":"gate, pool, gate, trees","correct_answer":"gate, then trees, then pool"}'::jsonb, 'Details come as they are remembered.', 'Offer "gate, pool, gate, trees" beside "gate, then trees, then pool" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Move in one direction through the place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION.M5_DC_CRITIQUE_PRAISE', 'ENGL.G5.WRITIN.T10_CREATIVE_WRITING_DES.DESCRIPTIVE_COMPOSITION', 'Gives only praise or only "nice" when critiquing.', '{"question":"Critique a classmate''s description.","wrong_answer":"It is nice.","correct_answer":"Good use of smell; the middle repeats \"big\"."}'::jsonb, 'Critique is seen as being kind.', 'Offer "It is nice." beside "Good use of smell; the middle repeats "big"." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say one strength and one thing to improve, with a reason.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.INTERROGATIVES.M_INT_WHO_WHAT', 'ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.INTERROGATIVES', 'Uses who for things or what for people.', '{"question":"___ is your class teacher?","wrong_answer":"What","correct_answer":"Who"}'::jsonb, 'Does not ask whether the answer is a person or a thing.', 'who and what swapped in a question about a person or a thing.', 'A person: who. A thing or idea: what.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.INTERROGATIVES.M_INT_WHEN_WHERE_WHY', 'ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.INTERROGATIVES', 'Mixes when (time), where (place) and why (reason).', '{"question":"\"___ did you arrive late?\" \"Because the bus broke down.\"","wrong_answer":"When","correct_answer":"Why"}'::jsonb, 'Does not read the answer to see what is being asked.', 'An answer that is a reason, a time or a place beside the wrong question word.', 'Because gives a reason: why. At six o''clock gives a time: when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.INTERROGATIVES.M_INT_WORD_ORDER', 'ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.INTERROGATIVES', 'Keeps statement order in a question (What you are doing?).', '{"question":"What ___?","wrong_answer":"you are doing","correct_answer":"are you doing"}'::jsonb, 'Kiswahili questions keep the same word order as statements.', 'A question with the subject before the helper verb.', 'In a question, the helper verb comes first: are you, did he, can she.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.INTERROGATIVES.M_INT_DO_MISSING', 'ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.INTERROGATIVES', 'Leaves out do, does or did (Why you came late?).', '{"question":"Why ___ late?","wrong_answer":"you came","correct_answer":"did you come"}'::jsonb, 'Drops the helper verb as in quick speech.', 'A question with no do, does or did.', 'With most verbs the question needs did, do or does, and the verb goes back to plain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.INTERROGATIVES.M_INT_ELSE_POSITION', 'ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.INTERROGATIVES', 'Puts else in the wrong place or adds another word (what other else).', '{"question":"Who ___ came to the party?","wrong_answer":"else other","correct_answer":"else"}'::jsonb, 'Adds a second word of the same meaning.', 'else with other or more.', 'Else already means "in addition". Use one word: who else, what else.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.INTERROGATIVES.M_INT_HOW_MUCH_MANY', 'ENGL.G5.GRAMMA.T11_USE_OF_INTERROGATIVE.INTERROGATIVES', 'Mixes how much (cannot be counted) and how many (can be counted).', '{"question":"How ___ goats does he have?","wrong_answer":"much","correct_answer":"many"}'::jsonb, 'Does not ask whether the thing can be counted.', 'how much with a countable noun, or how many with an uncountable one.', 'Goats can be counted: how many. Rice cannot be counted one by one: how much.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T11_SPELLING.HOMOPHONES.M_HOMO_THERE_THEIR', 'ENGL.G5.WRITIN.T11_SPELLING.HOMOPHONES', 'Mixes there, their and they''re.', '{"question":"The children left ___ bags in the classroom.","wrong_answer":"there","correct_answer":"their"}'::jsonb, 'The three words sound the same.', 'there/their/they''re in one sentence.', 'Their means belonging to them. There is a place. They''re means they are.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T11_SPELLING.HOMOPHONES.M_HOMO_TO_TOO_TWO', 'ENGL.G5.WRITIN.T11_SPELLING.HOMOPHONES', 'Mixes to, too and two.', '{"question":"Wanjiru has ___ brothers.","wrong_answer":"to","correct_answer":"two"}'::jsonb, 'The three words sound the same.', 'to/too/two in one sentence.', 'Two is the number. Too means also or more than needed. To is a direction word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T11_SPELLING.HOMOPHONES.M_HOMO_SOUND_ONLY', 'ENGL.G5.WRITIN.T11_SPELLING.HOMOPHONES', 'Chooses by sound alone, so picks whichever spelling comes to mind.', '{"question":"We ate the ___ of bread.","wrong_answer":"peace","correct_answer":"piece"}'::jsonb, 'Does not stop to think about the meaning.', 'Two words that sound the same where the meaning decides.', 'Say what the word means, then match it to the spelling: piece is a part, peace is calm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T11_SPELLING.HOMOPHONES.M_HOMO_HEAR_HERE', 'ENGL.G5.WRITIN.T11_SPELLING.HOMOPHONES', 'Mixes up hear and here, write and right, see and sea.', '{"question":"Come ___ and sit beside me.","wrong_answer":"hear","correct_answer":"here"}'::jsonb, 'Knows both spellings but not which meaning each carries.', 'hear/here, write/right, see/sea, meet/meat.', 'Hear has an ear in it. Here is about a place, like there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T11_SPELLING.HOMONYMS.M_HOMON_FIRST_MEANING', 'ENGL.G5.WRITIN.T11_SPELLING.HOMONYMS', 'Picks the commonest meaning of the word and ignores the one asked for.', '{"question":"Which sentence uses bank to mean the side of a river?","wrong_answer":"He saved money at the bank.","correct_answer":"We sat on the bank of the river."}'::jsonb, 'Knows only the first meaning learned.', 'The common meaning among the options next to the less common.', 'Read the whole sentence before you choose.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T11_SPELLING.HOMONYMS.M_HOMON_CONTEXT_IGNORED', 'ENGL.G5.WRITIN.T11_SPELLING.HOMONYMS', 'Matches on the word alone and does not check the other words in the sentence.', '{"question":"Which sentence uses bat to mean the animal that flies at night?","wrong_answer":"The batsman hit the ball with his bat.","correct_answer":"A bat flew out of the cave at dusk."}'::jsonb, 'Sees the same spelling and stops.', 'Two sentences with the same word and different surrounding clues.', 'Look for clue words: cave, night, wings; or ball, cricket.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T11_SPELLING.HOMONYMS.M5_HOMON_SPELL_DIFF', 'ENGL.G5.WRITIN.T11_SPELLING.HOMONYMS', 'Thinks homonyms are spelt differently.', '{"question":"Is \"bat\" (animal) and \"bat\" (cricket) a homonym pair?","wrong_answer":"No, they mean different things","correct_answer":"Yes, same spelling and sound, different meanings"}'::jsonb, 'Homonyms are confused with homophones.', 'Offer "No, they mean different things" beside "Yes, same spelling and sound, different meanings" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Homonyms are spelt and sound the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T11_SPELLING.HOMONYMS.M5_HOMON_ONE_MEANING_ONLY', 'ENGL.G5.WRITIN.T11_SPELLING.HOMONYMS', 'Knows only one meaning of the word.', '{"question":"\"The match was lit.\" Match here means ...","wrong_answer":"a football game","correct_answer":"a small stick for fire"}'::jsonb, 'Only the most common meaning is known.', 'Offer "a football game" beside "a small stick for fire" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Many words have more than one meaning: use the sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T12_WORD_CLASS_NOUNS.SAME_SINGULAR_PLURAL.M_NOUN_SHEEPS', 'ENGL.G5.GRAMMA.T12_WORD_CLASS_NOUNS.SAME_SINGULAR_PLURAL', 'Adds -s to a noun that does not change (sheeps, deers, aircrafts).', '{"question":"The farmer keeps twenty ___.","wrong_answer":"sheeps","correct_answer":"sheep"}'::jsonb, 'Applies the regular plural rule to every noun.', 'sheeps, deers and fishs among the options.', 'A few words stay the same: sheep, deer, fish, series, species, aircraft.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T12_WORD_CLASS_NOUNS.SAME_SINGULAR_PLURAL.M_NOUN_OVERREGULAR', 'ENGL.G5.GRAMMA.T12_WORD_CLASS_NOUNS.SAME_SINGULAR_PLURAL', 'Adds -s to an irregular plural (childs, mans, foots, tooths).', '{"question":"Many ___ were playing outside.","wrong_answer":"childs","correct_answer":"children"}'::jsonb, 'Applies the regular plural rule to a word that changes inside.', 'childs, mans, foots among the options.', 'Learn these by heart: child-children, man-men, foot-feet, tooth-teeth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T12_WORD_CLASS_NOUNS.SAME_SINGULAR_PLURAL.M_NOUN_VERB_AGREEMENT', 'ENGL.G5.GRAMMA.T12_WORD_CLASS_NOUNS.SAME_SINGULAR_PLURAL', 'Uses a singular verb with many sheep or fish (The sheep is grazing).', '{"question":"Fifty sheep ___ on the hill.","wrong_answer":"is","correct_answer":"are"}'::jsonb, 'Sees the noun without -s and takes it as singular.', 'A number before a same-form noun, and a singular verb.', 'Look for a number or many. Fifty sheep are; one sheep is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T12_WORD_CLASS_NOUNS.SAME_SINGULAR_PLURAL.M_NOUN_A_BEFORE_PLURAL', 'ENGL.G5.GRAMMA.T12_WORD_CLASS_NOUNS.SAME_SINGULAR_PLURAL', 'Puts a or one before a plural form (a sheeps; one fishes).', '{"question":"I saw ___ in the river.","wrong_answer":"a fishes","correct_answer":"a fish"}'::jsonb, 'Does not link a/an to a single thing.', 'a/an with a plural form.', 'A fish is one. Fish can also mean many, with a number: five fish.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_PARTS.M5_DP_LETTER', 'ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_PARTS', 'Takes a letter for a diary entry.', '{"question":"Is \"Dear Juma, how are you?\" a diary entry?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Both may start with Dear.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A diary is written to yourself or Dear Diary.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_PARTS.M5_DP_NO_DATE', 'ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_PARTS', 'Does not see the date as a part.', '{"question":"What part is missing: \"Today I planted a tree.\"?","wrong_answer":"nothing","correct_answer":"the date"}'::jsonb, 'The date is seen as optional.', 'Offer "nothing" beside "the date" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Every entry has a date.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_PARTS.M5_DP_THIRD_PERSON', 'ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_PARTS', 'Accepts an entry written in the third person.', '{"question":"Is \"She went to the river\" a diary sentence?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Story writing is carried over.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Diaries use I.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_PARTS.M5_DP_TIMETABLE', 'ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_PARTS', 'Takes a timetable of plans for a diary.', '{"question":"Is \"8 am: Maths, 9 am: English\" a diary entry?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'A diary is confused with a planner.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A diary records what happened and how you felt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_WRITING.M5_DW_FUTURE', 'ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_WRITING', 'Writes plans instead of what happened.', '{"question":"Write today''s entry about the clean-up.","wrong_answer":"Tomorrow we will clean the river.","correct_answer":"Today we cleaned the river bank."}'::jsonb, 'The diary is used as a planner.', 'Offer "Tomorrow we will clean the river." beside "Today we cleaned the river bank." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Write what happened today.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_WRITING.M5_DW_NO_FEELINGS', 'ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_WRITING', 'Lists events with no feelings.', '{"question":"Add a feeling: \"We picked up plastic.\"","wrong_answer":"We picked up plastic. We went home.","correct_answer":"We picked up plastic. I felt proud of our river."}'::jsonb, 'Only facts are thought to count.', 'Offer "We picked up plastic. We went home." beside "We picked up plastic. I felt proud of our river." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say how you felt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_WRITING.M5_DW_THIRD_PERSON', 'ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_WRITING', 'Writes about himself or herself as he or she.', '{"question":"Which is right for a diary?","wrong_answer":"Baraka cleaned the classroom.","correct_answer":"I cleaned the classroom."}'::jsonb, 'Story habits.', 'Offer "Baraka cleaned the classroom." beside "I cleaned the classroom." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use I.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_WRITING.M5_DW_ONE_ENTRY', 'ENGL.G5.WRITIN.T12_FUNCTIONAL_WRITING_D.DIARY_WRITING', 'Writes several days as one entry with one date.', '{"question":"You write about Monday and Tuesday. How many entries?","wrong_answer":"one","correct_answer":"two, each with its date"}'::jsonb, 'The diary is seen as one composition.', 'Offer "one" beside "two, each with its date" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One entry per day, each dated.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T13_PRONUNCIATION_AND_VO.JUDGE_ORAL.M5_JO_PERSON', 'ENGL.G5.LISTEN.T13_PRONUNCIATION_AND_VO.JUDGE_ORAL', 'Comments on the person, not the talk.', '{"question":"Give feedback on Juma''s talk.","wrong_answer":"Juma is my friend, so it was good.","correct_answer":"Your simile was clear, but speak louder."}'::jsonb, 'Friendship decides the judgement.', 'Offer "Juma is my friend, so it was good." beside "Your simile was clear, but speak louder." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Talk about the words, gestures and voice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T13_PRONUNCIATION_AND_VO.JUDGE_ORAL.M5_JO_LOUD_ONLY', 'ENGL.G5.LISTEN.T13_PRONUNCIATION_AND_VO.JUDGE_ORAL', 'Judges only by how loud the speaker was.', '{"question":"What made Amina''s talk good?","wrong_answer":"She was loud.","correct_answer":"She used clear words and fitting gestures."}'::jsonb, 'Loudness is the only thing noticed.', 'Offer "She was loud." beside "She used clear words and fitting gestures." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at word choice, similes and gestures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T13_PRONUNCIATION_AND_VO.JUDGE_ORAL.M5_JO_ONLY_FAULTS', 'ENGL.G5.LISTEN.T13_PRONUNCIATION_AND_VO.JUDGE_ORAL', 'Lists only mistakes.', '{"question":"Give one strength and one improvement.","wrong_answer":"You said eeh and you forgot a word.","correct_answer":"Your opening was strong. Next time, slow down."}'::jsonb, 'Feedback is seen as correction only.', 'Offer "You said eeh and you forgot a word." beside "Your opening was strong. Next time, slow down." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start with one strength.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.LISTEN.T13_PRONUNCIATION_AND_VO.JUDGE_ORAL.M5_JO_WRONG_SIMILE_OK', 'ENGL.G5.LISTEN.T13_PRONUNCIATION_AND_VO.JUDGE_ORAL', 'Accepts a simile that does not fit.', '{"question":"A speaker says the bank was \"as slow as a cheetah\". Is the simile right?","wrong_answer":"Yes","correct_answer":"No: a cheetah is fast"}'::jsonb, 'The child hears as ... as and thinks it is correct.', 'Offer "Yes" beside "No: a cheetah is fast" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check that the comparison makes sense.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_TIME_PLACE.M_PREP_DAY_IN', 'ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_TIME_PLACE', 'Uses in or at for a day or date (in Monday, at Saturday).', '{"question":"We have a test ___ Monday.","wrong_answer":"in","correct_answer":"on"}'::jsonb, 'Uses one preposition for all times.', 'in/at beside a day of the week or a date.', 'On for days and dates. At for clock times and moments. In for months, years and parts of the day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_TIME_PLACE.M_PREP_CLOCK_IN', 'ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_TIME_PLACE', 'Uses in or on for a clock time (in 8 o''clock).', '{"question":"The bus leaves ___ 8 o''clock.","wrong_answer":"in","correct_answer":"at"}'::jsonb, 'Uses in for every time.', 'in or on beside a clock time.', 'At for exact clock times and for night: at 8 o''clock, at night.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_TIME_PLACE.M_PREP_PART_OF_DAY', 'ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_TIME_PLACE', 'Uses at or on for parts of the day, months and years (at the morning).', '{"question":"I wake up early ___ the morning.","wrong_answer":"at","correct_answer":"in"}'::jsonb, 'Translates the Kiswahili phrase for each time word with the same word.', 'at/on beside morning, afternoon, evening, a month or a year.', 'In for morning, afternoon, evening, months, years and seasons.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_TIME_PLACE.M_PREP_PLACE', 'ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_TIME_PLACE', 'Mixes in, on and at for places (on the room, at the table in).', '{"question":"The cup is ___ the table.","wrong_answer":"in","correct_answer":"on"}'::jsonb, 'Does not think about how the thing sits in the place.', 'in/at beside a surface or a point.', 'On touches a surface, in is inside, at is a point or place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_DIRECTION.M_PREP_TO_HOME', 'ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_DIRECTION', 'Writes to home (went to home).', '{"question":"After school I went ___.","wrong_answer":"to home","correct_answer":"home"}'::jsonb, 'Kiswahili says kwenda nyumbani; the word for to is built into the verb.', 'to home among the options.', 'Home needs no to: go home, come home, walk home.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_DIRECTION.M_PREP_ENTER_INTO', 'ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_DIRECTION', 'Writes entered into for walking into a place.', '{"question":"The teacher entered ___ the classroom.","wrong_answer":"into","correct_answer":"nothing"}'::jsonb, 'Mixes into (movement) with the verb enter, which has the meaning built in.', 'entered into among the options.', 'Enter already means go into. Say entered the room, or went into the room.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_DIRECTION.M_PREP_TOWARDS_TO', 'ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_DIRECTION', 'Writes towards to, or uses to for a movement in the direction of.', '{"question":"The goats ran ___ the river.","wrong_answer":"towards to","correct_answer":"towards"}'::jsonb, 'Joins two direction words.', 'towards to among the options.', 'Towards is already a direction word. Use it alone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_DIRECTION.M_PREP_THROUGH_INTO', 'ENGL.G5.GRAMMA.T13_WORD_CLASS_PREPOSITI.PREPOSITIONS_DIRECTION', 'Mixes through (from one side to the other) with into (going inside).', '{"question":"The train went ___ a tunnel and came out the other side.","wrong_answer":"into","correct_answer":"through"}'::jsonb, 'Does not think about whether the movement ends inside or comes out.', 'into and through offered together.', 'Through goes in one side and out the other. Into stops inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T13_SPELLING.DOUBLE_LETTERS.M_SPELL_SINGLE_CONSONANT', 'ENGL.G5.WRITIN.T13_SPELLING.DOUBLE_LETTERS', 'Writes one consonant where two are needed (sumer, leter).', '{"question":"In ___ the days are hot.","wrong_answer":"sumer","correct_answer":"summer"}'::jsonb, 'Spells by sound and does not hear the double letter.', 'A word spelt with one consonant among the options.', 'Learn the double letters in common words: summer, letter, happy, address.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T13_SPELLING.DOUBLE_LETTERS.M_SPELL_EXTRA_DOUBLE', 'ENGL.G5.WRITIN.T13_SPELLING.DOUBLE_LETTERS', 'Doubles a letter that should be single, or doubles the wrong letter (adress, succes, comittee).', '{"question":"Please write your ___ on the form.","wrong_answer":"adress","correct_answer":"address"}'::jsonb, 'Guesses which letter to double.', 'A word with the wrong letter doubled.', 'Check every double letter: address has dd and ss.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T13_SPELLING.DOUBLE_LETTERS.M_SPELL_SINGLE_VOWEL', 'ENGL.G5.WRITIN.T13_SPELLING.DOUBLE_LETTERS', 'Writes one vowel where two are needed (fod, shep, wek).', '{"question":"We eat ___ every day.","wrong_answer":"fod","correct_answer":"food"}'::jsonb, 'Spells by the short sound.', 'A word with one vowel among the options.', 'The sound is long, so two vowels: oo, ee.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G5.WRITIN.T13_SPELLING.DOUBLE_LETTERS.M_SPELL_PHONETIC', 'ENGL.G5.WRITIN.T13_SPELLING.DOUBLE_LETTERS', 'Spells a word the way it sounds (sucess, coffe).', '{"question":"Mama drinks ___ every morning.","wrong_answer":"cofee","correct_answer":"coffee"}'::jsonb, 'Spells by ear and does not remember the shape of the word.', 'A word that is a sound-for-sound spelling.', 'Say the word in syllables and write each: cof-fee.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
